window.__TNPSC_REGISTER_TEST__("gk", 6, [{"id":501,"subject":"gk","testNumber":6,"question":"சூரியனில் தொடர்ந்து அளவற்ற வெப்பமும் ஒளியும் உருவாவதற்குக் காரணமான அணுக்கரு வினை எது?","options":["அணுக்கரு இணைவு","கதிரியக்கச் சிதைவு","வேதி எரிதல் வினை","அணுக்கருப் பிளவு"],"correctAnswer":0,"explanation":"சூரியனின் மையப்பகுதியில் மிக அதிக வெப்பநிலை மற்றும் அழுத்தத்தின் காரணமாக ஹைட்ரஜன் அணுக்கள் இணைந்து ஹீலியம் அணுக்களாக மாறும் 'அணுக்கரு இணைவு' (Nuclear Fusion) வினை நிகழ்கிறது. இதன் மூலமே சூரியனிலிருந்து தொடர்ந்து அபரிமிதமான வெப்பமும் ஒளியும் வெளிப்படுகின்றன.","difficulty":"easy","topic":"சூரிய குடும்பம்"},{"id":502,"subject":"gk","testNumber":6,"question":"சூரியக் குடும்பத்தில் மிக வெப்பமான கோள் மற்றும் கிழக்கிலிருந்து மேற்காகச் சுழலும் 'விடிவெள்ளி' என அழைக்கப்படும் கோள் எது?","options":["வியாழன்","புதன்","செவ்வாய்","வெள்ளி"],"correctAnswer":3,"explanation":"வெள்ளி (Venus) கோளின் வளிமண்டலத்தில் சுமார் 96% கார்பன் டை ஆக்சைடு உள்ளதால் கடுமையான பசுமை இல்ல விளைவு ஏற்பட்டு சூரியக் குடும்பத்தின் மிக வெப்பமான கோளாகத் திகழ்கிறது. மேலும் இது மற்ற பெரும்பாலான கோள்களுக்கு மாறாகக் கிழக்கிலிருந்து மேற்காகத் தன்னைத்தானே சுற்றிக்கொள்கிறது.","difficulty":"easy","topic":"சூரிய குடும்பம்"},{"id":503,"subject":"gk","testNumber":6,"question":"'செந்நிறக் கோள்' என அழைக்கப்படும் செவ்வாய் கோளின் இரண்டு இயற்கைத் துணைக்கோள்கள் எவை?","options":["டைட்டன் மற்றும் ரியா","கானிமீடு மற்றும் யூரோப்பா","போபஸ் மற்றும் டீமோஸ்","டிரைட்டன் மற்றும் மிராண்டா"],"correctAnswer":2,"explanation":"செவ்வாய் கோளின் மேற்பரப்பில் இரும்பு ஆக்சைடு அதிகமாக இருப்பதால் அது செந்நிறமாகக் காட்சியளிக்கிறது. செவ்வாய் கோளுக்கு போபஸ் (Phobos) மற்றும் டீமோஸ் (Deimos) ஆகிய இரண்டு சிறிய இயற்கைத் துணைக்கோள்கள் உள்ளன.","difficulty":"medium","topic":"சூரிய குடும்பம்"},{"id":504,"subject":"gk","testNumber":6,"question":"சூரியக் குடும்பத்தின் மிகப்பெரிய கோளான வியாழனின் மிகப்பெரிய துணைக்கோள் எது?","options":["காலிஸ்டோ","கானிமீடு","டைட்டன்","டிரைட்டன்"],"correctAnswer":1,"explanation":"வியாழன் (Jupiter) சூரியக் குடும்பத்தின் மிகப்பெரிய கோளாகும். அதன் துணைக்கோளான கானிமீடு (Ganymede) சூரியக் குடும்பத்திலேயே மிகப்பெரிய துணைக்கோள் ஆகும்; இது புதன் கோளை விடவும் அளவில் பெரியது.","difficulty":"easy","topic":"சூரிய குடும்பம்"},{"id":505,"subject":"gk","testNumber":6,"question":"நீரின் அடர்த்தியை விடக் குறைவான அடர்த்தியைக் கொண்டிருப்பதால், பெரிய நீர்நிலையில் இட்டால் மிதக்கும் தன்மை கொண்ட கோள் எது?","options":["நெப்டியூன்","சனி","யுரேனஸ்","புதன்"],"correctAnswer":1,"explanation":"சனி (Saturn) கோளின் சராசரி அடர்த்தி சுமார் 0.687 கி/செ.மீ³ ஆகும், இது நீரின் அடர்த்தியை (1 கி/செ.மீ³) விடக் குறைவானது. அழகிய வளையங்களைக் கொண்ட சனி கோளின் மிகப்பெரிய துணைக்கோள் டைட்டன் ஆகும்.","difficulty":"medium","topic":"சூரிய குடும்பம்"},{"id":506,"subject":"gk","testNumber":6,"question":"'உருளும் கோள்' (Rolling Planet) என அழைக்கப்படும் யுரேனஸ் கோள் பச்சை நிறத்தில் தோன்றுவதற்குக் காரணமான வாயு எது?","options":["சல்பர் டை ஆக்சைடு","மீத்தேன்","கார்பன் டை ஆக்சைடு","நைட்ரஜன்"],"correctAnswer":1,"explanation":"யுரேனஸ் கோள் தனது சுற்றுப்பாதையில் சுமார் 98° சாய்ந்திருப்பதால் உருண்டு ஓடுவது போல் காணப்படுகிறது. இதன் வளிமண்டலத்தில் உள்ள மீத்தேன் (Methane) வாயு சிவப்பு ஒளியை உறிஞ்சி நீல-பச்சை ஒளியைப் பிரதிபலிப்பதால் இக்கோள் பச்சை நிறமாகத் தோன்றுகிறது.","difficulty":"hard","topic":"சூரிய குடும்பம்"},{"id":507,"subject":"gk","testNumber":6,"question":"சூரியக் குடும்பத்தில் 'சிறுகோள் மண்டலம்' (Asteroid Belt) எந்த இரு கோள்களின் சுற்றுப்பாதைகளுக்கு இடையில் அமைந்துள்ளது?","options":["புதன் மற்றும் வெள்ளி","செவ்வாய் மற்றும் வியாழன்","வியாழன் மற்றும் சனி","புவி மற்றும் செவ்வாய்"],"correctAnswer":1,"explanation":"உட்கோள்கள் (புதன், வெள்ளி, புவி, செவ்வாய்) மற்றும் வெளிக்கோள்கள் (வியாழன், சனி, யுரேனஸ், நெப்டியூன்) ஆகியவற்றைப் பிரிக்கும் வகையில் செவ்வாய் மற்றும் வியாழன் கோள்களின் சுற்றுப்பாதைகளுக்கு இடையே சிறுகோள் மண்டலம் அமைந்துள்ளது.","difficulty":"easy","topic":"சூரிய குடும்பம்"},{"id":508,"subject":"gk","testNumber":6,"question":"சூரியனிலிருந்து புறப்படும் ஒளி புவியை வந்தடைய எடுத்துக்கொள்ளும் தோராயமான நேரம் எவ்வளவு?","options":["சுமார் 4.2 நிமிடங்கள்","சுமார் 12.5 நிமிடங்கள்","சுமார் 8.3 நிமிடங்கள்","சுமார் 1.3 வினாடிகள்"],"correctAnswer":2,"explanation":"சூரியனுக்கும் புவிக்கும் இடையேயான சராசரித் தொலைவு சுமார் 150 மில்லியன் கிலோமீட்டர் (1 வானியல் அலகு) ஆகும். வினாடிக்கு 3 லட்சம் கி.மீ வேகத்தில் பயணிக்கும் சூரிய ஒளி புவியை வந்தடைய சுமார் 8.3 நிமிடங்கள் (8 நிமிடம் 20 வினாடிகள்) ஆகிறது.","difficulty":"easy","topic":"சூரிய குடும்பம்"},{"id":509,"subject":"gk","testNumber":6,"question":"சந்திர கிரகணம் (Lunar Eclipse) எவ்வாறு மற்றும் எப்போது நிகழ்கிறது?","options":["புவிக்கும் நிலவுக்கும் இடையே சூரியன் வரும்போது, பௌர்ணமி நாளில்","சூரியனுக்கும் நிலவுக்கும் இடையே புவி வரும்போது, பௌர்ணமி நாளில்","சூரியனுக்கும் புவிக்கும் இடையே நிலவு வரும்போது, அமாவாசை நாளில்","நிலவுக்கும் செவ்வாய்க்கும் இடையே புவி வரும்போது, அமாவாசை நாளில்"],"correctAnswer":1,"explanation":"சூரியன், புவி மற்றும் நிலவு ஆகிய மூன்றும் ஒரே நேர்க்கோட்டில் அமைந்து, சூரியனுக்கும் நிலவுக்கும் இடையே புவி வரும்போது புவியின் நிழல் நிலவின் மீது விழுகிறது. இதுவே சந்திர கிரகணம் எனப்படும்; இது பௌர்ணமி நாளில் மட்டுமே நிகழும்.","difficulty":"easy","topic":"சூரிய மற்றும் சந்திர கிரகணம்"},{"id":510,"subject":"gk","testNumber":6,"question":"சூரிய கிரகணம் (Solar Eclipse) நிகழ்வதற்கான சரியான வானியல் அமைப்பு மற்றும் நாள் எது?","options":["சூரியன் - நிலவு - புவி (அமாவாசை நாள்)","சூரியன் - நிலவு - புவி (பௌர்ணமி நாள்)","சூரியன் - புவி - நிலவு (பௌர்ணமி நாள்)","நிலவு - சூரியன் - புவி (அமாவாசை நாள்)"],"correctAnswer":0,"explanation":"சூரியனுக்கும் புவிக்கும் இடையே நிலவு நேர்க்கோட்டில் வரும்போது, நிலவின் நிழல் புவியின் ஒரு பகுதியில் விழுந்து சூரியனை மறைக்கிறது. இதுவே சூரிய கிரகணம் எனப்படும்; இது அமாவாசை நாளில் மட்டுமே ஏற்படும்.","difficulty":"medium","topic":"சூரிய மற்றும் சந்திர கிரகணம்"},{"id":511,"subject":"gk","testNumber":6,"question":"புவியின் தற்சுழற்சியால் (Rotation) ஏற்படும் முதன்மை விளைவு என்ன?","options":["பருவகால மாற்றங்கள் ஏற்படுதல்","சூரிய கிரகணம் ஏற்படுதல்","சம இரவு-பகல் நாட்கள் ஏற்படுதல்","பகல் மற்றும் இரவு ஏற்படுதல்"],"correctAnswer":3,"explanation":"புவி தனது அச்சில் மேற்கிலிருந்து கிழக்காக சுமார் 23 மணி 56 நிமிடம் 4 வினாடிகளில் (ஒரு நாள்) ஒருமுறை தன்னைத்தானே சுற்றிக்கொள்கிறது. இந்தத் தற்சுழற்சியால் சூரியனை நோக்கியுள்ள பகுதி பகலாகவும், எதிர் பகுதி இரவாகவும் மாறி மாறி ஏற்படுகின்றன.","difficulty":"easy","topic":"புவி இயக்கம்"},{"id":512,"subject":"gk","testNumber":6,"question":"புவியில் கோடை, குளிர், வசந்தம், இலையுதிர் ஆகிய பருவகாலங்கள் (Seasons) தோன்றுவதற்குக் காரணம் என்ன?","options":["நிலவின் ஈர்ப்பு விசை மற்றும் ஓதங்கள்","புவியின் காந்தப்புலம் மாறுபடுவது","புவியின் தற்சுழற்சி மட்டுமே","புவியின் அச்சுச் சாய்வும் சூரியனைச் சுற்றி வருதலும்"],"correctAnswer":3,"explanation":"புவி தனது செங்குத்து அச்சிலிருந்து 23½° சாய்ந்த நிலையில் (சுற்றுப்பாதை தளத்திற்கு 66½° கோணத்தில்) சூரியனைச் சுற்றி வருவதால், சூரியனின் செங்குத்துக் கதிர்கள் ஆண்டின் வெவ்வேறு காலங்களில் வெவ்வேறு அட்சப் பகுதிகளில் விழுகின்றன. இதனாலேயே பருவகாலங்கள் மாறுகின்றன.","difficulty":"medium","topic":"புவி இயக்கம்"},{"id":513,"subject":"gk","testNumber":6,"question":"புவியில் அனைத்து இடங்களிலும் பகலும் இரவும் சம அளவாக இருக்கும் 'சம இரவு-பகல் நாட்கள்' (Equinoxes) எவை?","options":["மார்ச் 21 மற்றும் செப்டம்பர் 23","ஜூன் 21 மற்றும் டிசம்பர் 22","ஏப்ரல் 21 மற்றும் அக்டோபர் 23","ஜனவரி 3 மற்றும் ஜூலை 4"],"correctAnswer":0,"explanation":"மார்ச் 21 (வசந்தகால சம இரவு-பகல் நாள்) மற்றும் செப்டம்பர் 23 (இலையுதிர்கால சம இரவு-பகல் நாள்) ஆகிய இரு நாட்களிலும் சூரியனின் செங்குத்துக் கதிர்கள் பூமத்திய ரேகையின் மீது நேராக விழுகின்றன. இதனால் உலகம் முழுவதும் பகலும் இரவும் சமமாக (12 மணி நேரம்) இருக்கும்.","difficulty":"medium","topic":"புவி இயக்கம்"},{"id":514,"subject":"gk","testNumber":6,"question":"வட அரைக்கோளத்தில் மிக நீண்ட பகல் பொழுதும் மிகக் குறுகிய இரவுப் பொழுதும் கொண்ட 'கோடைக் கதிர்த்திருப்பம்' (Summer Solstice) எந்த நாளில் நிகழ்கிறது?","options":["ஜூன் 21","மார்ச் 21","டிசம்பர் 22","செப்டம்பர் 23"],"correctAnswer":0,"explanation":"ஜூன் 21 அன்று சூரியனின் செங்குத்துக் கதிர்கள் 23½° வடக்கு அட்சமான கடக ரேகையின் மீது நேராக விழுகின்றன. இதனால் வட அரைக்கோளத்தில் மிக நீண்ட பகல் பொழுதும் கோடைக்காலமும் ஏற்படுகின்றன; இதே நாளில் தென் அரைக்கோளத்தில் குளிர்காலம் நிலவும்.","difficulty":"medium","topic":"புவி இயக்கம்"},{"id":515,"subject":"gk","testNumber":6,"question":"புவியில் 1° இடைவெளியில் வரையப்படும் அட்சக் கோடுகள் (பூமத்திய ரேகை மற்றும் இரு துருவங்கள் உட்பட) மற்றும் தீர்க்கக் கோடுகளின் மொத்த எண்ணிக்கை முறையே எத்தனை?","options":["181 மற்றும் 360","179 மற்றும் 180","180 மற்றும் 180","90 மற்றும் 360"],"correctAnswer":0,"explanation":"பூமத்திய ரேகை (0°), வட அரைக்கோளத்தில் 90 அட்சங்கள் மற்றும் தென் அரைக்கோளத்தில் 90 அட்சங்கள் என மொத்தம் 181 அட்சங்கள் உள்ளன. அதேபோல் 0° கிரீன்விச் கோட்டிலிருந்து கிழக்கே 179, மேற்கே 179, 0° மற்றும் 180° என மொத்தம் 360 தீர்க்கக்கோடுகள் உள்ளன.","difficulty":"hard","topic":"அட்ச மற்றும் தீர்க்கக் கோடுகள்"},{"id":516,"subject":"gk","testNumber":6,"question":"பின்வரும் முக்கிய அட்சக் கோடுகளில் இந்தியாவின் ஏறத்தாழ மையப் பகுதியின் வழியாகக் கடந்து செல்லும் கோடு எது?","options":["மகர ரேகை (23½° தெற்கு)","கடக ரேகை (23½° வடக்கு)","பூமத்திய ரேகை (0°)","ஆர்க்டிக் வட்டம் (66½° வடக்கு)"],"correctAnswer":1,"explanation":"கடக ரேகை (23½° வடக்கு அட்சம்) இந்தியாவின் வழியாக 8 மாநிலங்களைக் (குஜராத், ராஜஸ்தான், மத்தியப் பிரதேசம், சத்தீஸ்கர், ஜார்க்கண்ட், மேற்கு வங்காளம், திரிபுரா, மிசோரம்) கடந்து செல்கிறது. இது இந்தியாவை வெப்ப மண்டலம் மற்றும் மித வெப்ப மண்டலம் என இரு பகுதிகளாகப் பிரிக்கிறது.","difficulty":"easy","topic":"அட்ச மற்றும் தீர்க்கக் கோடுகள்"},{"id":517,"subject":"gk","testNumber":6,"question":"கிரீன்விச் சராசரி நேரத்தை (GMT) விட இந்தியத் திட்ட நேரம் (IST) எவ்வளவு கால அளவு முன்னதாக உள்ளது?","options":["4 மணி 30 நிமிடங்கள் முன்னதாக","5 மணி 30 நிமிடங்கள் பின்னதாக","5 மணி 30 நிமிடங்கள் முன்னதாக","6 மணி நேரம் முன்னதாக"],"correctAnswer":2,"explanation":"இந்தியத் திட்ட நேரம் 82½° கிழக்குத் தீர்க்கக்கோட்டை (உத்தரப் பிரதேசத்தின் மிர்சாபூர் வழியாகச் செல்லும் கோடு) அடிப்படையாகக் கொண்டு கணக்கிடப்படுகிறது. 1° தீர்க்கக்கோட்டிற்கு 4 நிமிடங்கள் என்பதால், 82.5 × 4 = 330 நிமிடங்கள் = 5 மணி 30 நிமிடங்கள் GMT-ஐ விட முன்னதாக உள்ளது.","difficulty":"easy","topic":"அட்ச மற்றும் தீர்க்கக் கோடுகள்"},{"id":518,"subject":"gk","testNumber":6,"question":"புவி தனது அச்சில் சுழலும்போது 1° தீர்க்கக்கோட்டைக் கடக்க எடுத்துக்கொள்ளும் நேரம் எவ்வளவு?","options":["15 நிமிடங்கள்","4 நிமிடங்கள்","1 நிமிடம்","60 நிமிடங்கள்"],"correctAnswer":1,"explanation":"புவி 24 மணி நேரத்தில் (1,440 நிமிடங்கள்) 360° தீர்க்கக்கோடுகளைச் சுற்றி வருகிறது. எனவே 1° தீர்க்கக்கோட்டைக் கடக்க 1440 / 360 = 4 நிமிடங்கள் ஆகிறது; மேலும் 1 மணி நேரத்தில் புவி 15° தீர்க்கக்கோடுகளைக் கடக்கிறது.","difficulty":"medium","topic":"அட்ச மற்றும் தீர்க்கக் கோடுகள்"},{"id":519,"subject":"gk","testNumber":6,"question":"பசிபிக் பெருங்கடலின் வழியாகச் செல்லும் 180° தீர்க்கக்கோடு எவ்வாறு அழைக்கப்படுகிறது?","options":["கிரீன்விச் முதன்மைத் தீர்க்கக்கோடு","பன்னாட்டுத் தேதிக்கோடு","வெப்பச் சமநிலைக்கோடு","பூமத்திய மையக்கோடு"],"correctAnswer":1,"explanation":"180° தீர்க்கக்கோடு 'பன்னாட்டுத் தேதிக்கோடு' (International Date Line) என அழைக்கப்படுகிறது. ஒரே நாட்டில் இரு வெவ்வேறு தேதிகள் ஏற்படுவதைத் தவிர்க்க இக்கோடு பசிபிக் பெருங்கடலில் உள்ள தீவுகளைத் தவிர்த்து வளைந்து நெளிந்து வரையப்பட்டுள்ளது.","difficulty":"medium","topic":"அட்ச மற்றும் தீர்க்கக் கோடுகள்"},{"id":520,"subject":"gk","testNumber":6,"question":"புவியின் மேலோட்டின் கண்டப் பகுதி 'சியால்' (SIAL) என அழைக்கப்படுவதற்குக் காரணம் அதில் மிகுதியாக உள்ள தனிமங்கள் எவை?","options":["சிலிக்கா மற்றும் அலுமினியம்","சல்பர் மற்றும் அலுமினியம்","சிலிக்கா மற்றும் மெக்னீசியம்","சோடியம் மற்றும் இரும்பு"],"correctAnswer":0,"explanation":"புவியின் மேலோட்டின் மேற்பகுதியான கண்டப் பகுதி சிலிக்கா (Si) மற்றும் அலுமினியம் (Al) ஆகிய தாதுக்களால் ஆனதால் 'சியால்' (SIAL) எனப்படுகிறது. இதன் கீழே உள்ள பெருங்கடல் தரைப்பகுதி சிலிக்கா மற்றும் மெக்னீசியத்தால் ஆனதால் 'சிமா' (SIMA) எனப்படுகிறது.","difficulty":"easy","topic":"புவியின் உள்ளமைப்பு"},{"id":521,"subject":"gk","testNumber":6,"question":"புவியின் மையப்பகுதியான கருவம் (Core) 'நைப்' (NIFE) என அழைக்கப்படக் காரணமான தனிமங்கள் எவை?","options":["நைட்ரஜன் மற்றும் இரும்பு","நியான் மற்றும் புளோரின்","நிக்கல் மற்றும் இரும்பு","நிக்கல் மற்றும் பாஸ்பரஸ்"],"correctAnswer":2,"explanation":"புவியின் மிக ஆழமான மைய அடுக்கான கருவத்தில் நிக்கல் (Ni) மற்றும் இரும்பு (Fe - ஃபெர்ரம்) ஆகிய கனமான உலோகங்கள் மிகுதியாக உள்ளதால் அது 'நைப்' (NIFE) என அழைக்கப்படுகிறது. இதன் வெளிப்பகுதி திரவ நிலையிலும், உட்பகுதி அதிக அழுத்தத்தால் திட நிலையிலும் உள்ளது.","difficulty":"easy","topic":"புவியின் உள்ளமைப்பு"},{"id":522,"subject":"gk","testNumber":6,"question":"புவியின் மேலோட்டையும் (Crust) கவசத்தையும் (Mantle) பிரிக்கும் எல்லைப்பகுதி எவ்வாறு அழைக்கப்படுகிறது?","options":["கான்ராட் எல்லை","குட்டன்பெர்க் எல்லை","மோஹோரோவிசிக் எல்லை","லெஹ்மன் எல்லை"],"correctAnswer":2,"explanation":"புவியின் மேலோட்டிற்கும் கவசத்திற்கும் இடையேயான எல்லை 'மோஹோரோவிசிக் எல்லை' (Mohorovicic Discontinuity) எனப்படுகிறது. அதேபோல் கவசத்தையும் கருவத்தையும் பிரிக்கும் எல்லை 'குட்டன்பெர்க் எல்லை' என அழைக்கப்படுகிறது.","difficulty":"hard","topic":"புவியின் உள்ளமைப்பு"},{"id":523,"subject":"gk","testNumber":6,"question":"மற்ற அனைத்துப் பாறை வகைகளும் உருவாவதற்கு அடிப்படையாக உள்ளதால் 'முதன்மைப் பாறைகள்' அல்லது 'தாய்ப் பாறைகள்' என அழைக்கப்படுபவை எவை?","options":["தீப்பாறைகள்","உருமாறிய பாறைகள்","சுண்ணாம்புப் பாறைகள்","படிவுப் பாறைகள்"],"correctAnswer":0,"explanation":"புவியின் உட்பகுதியிலிருந்து வெளிவரும் உருகிய பாறைக்குழம்பு (மேக்மா அல்லது லாவா) குளிர்ந்து திடமாவதால் தீப்பாறைகள் (Igneous Rocks) உருவாகின்றன. மற்ற படிவு மற்றும் உருமாறிய பாறைகள் இவற்றிலிருந்தே நேரடியாகவோ மறைமுகமாகவோ உருவாவதால் இவை முதன்மைப் பாறைகள் எனப்படுகின்றன.","difficulty":"easy","topic":"பாறை வகைகள்"},{"id":524,"subject":"gk","testNumber":6,"question":"தொல்லுயிர் எச்சங்கள் (Fossils) மற்றும் நிலக்கரி, பெட்ரோலியம் போன்ற படிம எரிபொருள்கள் எந்த வகைப் பாறைகளில் காணப்படுகின்றன?","options":["படிவுப் பாறைகள்","படிக உருமாறிய பாறைகள்","வெளித்தள்ளப்பட்ட தீப்பாறைகள்","ஊடுருவிய தீப்பாறைகள்"],"correctAnswer":0,"explanation":"ஆறுகள், காற்று மற்றும் பனியாறுகளால் கடத்தப்படும் மண் மற்றும் உயிரினங்களின் எச்சங்கள் அடுக்கு அடுக்காகப் படிந்து இறுகுவதால் படிவுப் பாறைகள் (Sedimentary Rocks) உருவாகின்றன. மணற்கல், சுண்ணாம்புக்கல், நிலக்கரி ஆகியவை படிவுப் பாறைகளுக்குச் சிறந்த எடுத்துக்காட்டுகளாகும்.","difficulty":"medium","topic":"பாறை வகைகள்"},{"id":525,"subject":"gk","testNumber":6,"question":"படிவுப் பாறையான சுண்ணாம்புக்கல் (Limestone) அதிக வெப்பம் மற்றும் அழுத்தத்திற்கு உட்படும்போது உருமாறி எந்தப் பாறையாக மாறுகிறது?","options":["குவார்ட்சைட்","பலகைக்கல் (Slate)","கிரானைட்","சலவைக்கல் (பளிங்கு)"],"correctAnswer":3,"explanation":"சுண்ணாம்புக்கல் அதிக வெப்பம் மற்றும் அழுத்தத்தால் உருமாறி சலவைக்கல்லாக (Marble) மாறுகிறது. இதேபோல் மணற்கல் குவார்ட்சைட்டாகவும், களிமண் பாறை பலகைக்கல்லாகவும் (Slate), கிரானைட் நைஸ் (Gneiss) பாறையாகவும் உருமாறுகின்றன.","difficulty":"medium","topic":"பாறை வகைகள்"},{"id":526,"subject":"gk","testNumber":6,"question":"புவிக்கு அடியில் நிலநடுக்கம் முதலில் தோன்றும் மையப்புள்ளி எவ்வாறு அழைக்கப்படுகிறது?","options":["பிளவுப் பள்ளத்தாக்கு","நிலநடுக்க மையம் (Focus / Hypocentre)","நிலநடுக்க மேல்மையம் (Epicentre)","அதிர்வு வளைவு"],"correctAnswer":1,"explanation":"புவியின் உட்பகுதியில் நிலநடுக்கம் தோன்றும் புள்ளி 'நிலநடுக்க மையம்' (Focus அல்லது Hypocentre) எனப்படுகிறது. அதற்கு நேர் செங்குத்தாகப் புவியின் மேற்பரப்பில் அமைந்துள்ள புள்ளி 'நிலநடுக்க மேல்மையம்' (Epicentre) என அழைக்கப்படுகிறது; இங்குதான் சேதம் அதிகமாக இருக்கும்.","difficulty":"medium","topic":"நிலநடுக்கம்"},{"id":527,"subject":"gk","testNumber":6,"question":"நிலநடுக்க அலைகளைப் பதிவு செய்யும் கருவி மற்றும் நிலநடுக்கத்தின் ஆற்றல் அளவை (Magnitude) அளவிடும் அளவுகோல் முறையே எவை?","options":["சீஸ்மோகிராப் மற்றும் ரிக்டர் அளவுகோல்","பாரோமீட்டர் மற்றும் மெர்கல்லி அளவுகோல்","ஹைக்ரோமீட்டர் மற்றும் பியூபோர்ட் அளவுகோல்","அனிமோமீட்டர் மற்றும் ரிக்டர் அளவுகோல்"],"correctAnswer":0,"explanation":"நிலநடுக்க அதிர்வுகளைப் பதிவு செய்யும் கருவி 'சீஸ்மோகிராப்' (நிலநடுக்கமானி) எனப்படும். நிலநடுக்கத்தின்போது வெளிப்படும் ஆற்றலின் அளவை அளவிட 1935-ஆம் ஆண்டு சார்லஸ் ரிக்டர் உருவாக்கிய 'ரிக்டர் அளவுகோல்' பயன்படுத்தப்படுகிறது.","difficulty":"easy","topic":"நிலநடுக்கம்"},{"id":528,"subject":"gk","testNumber":6,"question":"நிலநடுக்க அலைகளில் திட, திரவ மற்றும் வாயு ஆகிய மூன்று ஊடகங்களின் வழியாகவும் பயணிக்கும் மிக வேகமான அலைகள் எவை?","options":["இரண்டாம் நிலை அலைகள் (S-அலைகள்)","மேற்பரப்பு அலைகள் (L-அலைகள்)","ரேலே அலைகள்","முதன்மை அலைகள் (P-அலைகள்)"],"correctAnswer":3,"explanation":"முதன்மை அலைகள் (P-Waves) மிக வேகமாகப் பயணித்து நிலநடுக்கமானியை முதலில் அடையும் நெட்டலைகள் ஆகும்; இவை திட, திரவ, வாயு என அனைத்து ஊடகங்களிலும் பயணிக்கும். ஆனால் S-அலைகள் திடப் பொருட்களில் மட்டுமே பயணிக்கும்; மேற்பரப்பு (L) அலைகள் அதிக அழிவை ஏற்படுத்துகின்றன.","difficulty":"hard","topic":"நிலநடுக்கம்"},{"id":529,"subject":"gk","testNumber":6,"question":"உலகின் சுமார் 75% செயல்படும் எரிமலைகள் மற்றும் பெரும்பாலான நிலநடுக்கங்கள் நிகழும் 'நெருப்பு வளையம்' (Ring of Fire) எந்தப் பெருங்கடலைச் சூழ்ந்துள்ளது?","options":["ஆர்க்டிக் பெருங்கடல்","இந்தியப் பெருங்கடல்","அட்லாண்டிக் பெருங்கடல்","பசிபிக் பெருங்கடல்"],"correctAnswer":3,"explanation":"பசிபிக் பெருங்கடலைச் சுற்றியுள்ள புவித் தட்டுகளின் விளிம்புப் பகுதிகளில் உலகின் பெரும்பாலான எரிமலைகளும் நிலநடுக்கங்களும் நிகழ்கின்றன. இதனால் இப்பகுதி 'பசிபிக் நெருப்பு வளையம்' (Pacific Ring of Fire) என்று அழைக்கப்படுகிறது.","difficulty":"easy","topic":"எரிமலைகள்"},{"id":530,"subject":"gk","testNumber":6,"question":"தொடர்ந்து ஒளி வீசும் எரிமலைக் குழம்பை வெளியேற்றுவதால் 'மத்திய தரைக்கடலின் கலங்கரை விளக்கம்' என்று அழைக்கப்படும் எரிமலை எது?","options":["மவுண்ட் ஃபியூஜி","கிளிமஞ்சாரோ","ஸ்ட்ராம்போலி","கிரகடோவா"],"correctAnswer":2,"explanation":"இத்தாலியின் சிசிலி தீவுக்கு வடக்கே மத்திய தரைக்கடலில் அமைந்துள்ள ஸ்ட்ராம்போலி (Stromboli) எரிமலை தொடர்ந்து சீரான இடைவெளியில் வெடித்து ஒளி வீசுவதால் 'மத்திய தரைக்கடலின் கலங்கரை விளக்கம்' என அழைக்கப்படுகிறது.","difficulty":"medium","topic":"எரிமலைகள்"},{"id":531,"subject":"gk","testNumber":6,"question":"'மத்தியத் தரைக்கடலின் கலங்கரை விளக்கம்' (Lighthouse of the Mediterranean) என்று அழைக்கப்படும் செயல்படும் எரிமலை எது?","options":["ஃபியூஜியாமா","ஸ்ட்ராம்போலி","கிலிமஞ்சாரோ","கிரகடோவா"],"correctAnswer":1,"explanation":"இத்தாலியின் சிசிலித் தீவிற்கு வடக்கே மத்தியத் தரைக்கடலில் அமைந்துள்ள ஸ்ட்ராம்போலி (Stromboli) எரிமலை தொடர்ந்து நெருப்புக் குழம்பையும் ஒளியையும் வெளியிடுவதால் 'மத்தியத் தரைக்கடலின் கலங்கரை விளக்கம்' என்று அழைக்கப்படுகிறது.","difficulty":"easy","topic":"எரிமலைகள்"},{"id":532,"subject":"gk","testNumber":6,"question":"மேகம் உருவாதல், மழை, இடி, மின்னல் மற்றும் புயல் போன்ற அனைத்து வானிலை நிகழ்வுகளும் நடைபெறும் வளிமண்டல அடுக்கு எது?","options":["அடுக்குவளிமண்டலம் (Stratosphere)","அடிவளிமண்டலம் (Troposphere)","இடைவளிமண்டலம் (Mesosphere)","வெப்பவளிமண்டலம் (Thermosphere)"],"correctAnswer":1,"explanation":"புவியின் மேற்பரப்பை ஒட்டியுள்ள மிகக் கீழ் அடுக்கான அடிவளிமண்டலம் (Troposphere) 'வானிலை உருவாக்கும் அடுக்கு' எனப்படுகிறது. இங்கு உயரம் அதிகரிக்கும்போது ஒவ்வொரு 1,000 மீட்டருக்கும் 6.5°C என்ற அளவில் வெப்பநிலை குறைகிறது.","difficulty":"easy","topic":"வளிமண்டல அடுக்குகள்"},{"id":533,"subject":"gk","testNumber":6,"question":"சூரியனின் தீங்கு விளைவிக்கும் புறஊதாக் கதிர்களை (UV Rays) உறிஞ்சி உயிரினங்களைப் பாதுகாக்கும் ஓசோன் படலம் எந்த வளிமண்டல அடுக்கில் அமைந்துள்ளது?","options":["வெளிவளிமண்டலம் (Exosphere)","அடுக்குவளிமண்டலம் (Stratosphere)","அடிவளிமண்டலம் (Troposphere)","இடைவளிமண்டலம் (Mesosphere)"],"correctAnswer":1,"explanation":"அடுக்குவளிமண்டலத்தில் (Stratosphere) சுமார் 15 முதல் 35 கி.மீ உயரத்தில் ஓசோன் படலம் செறிந்து காணப்படுகிறது. மேலும் இவ்வடுக்கில் மேகங்களும் புயல்களும் இல்லாததால் ஜெட் விமானங்கள் பறப்பதற்கு மிகவும் ஏற்றதாக உள்ளது.","difficulty":"easy","topic":"வளிமண்டல அடுக்குகள்"},{"id":534,"subject":"gk","testNumber":6,"question":"புவி நோக்கி வரும் விண்கற்கள் (Meteors) உராய்வின் காரணமாக எரிந்து சாம்பலாகும் வளிமண்டலத்தின் மிகக் குளிரான அடுக்கு எது?","options":["அடுக்குவளிமண்டலம்","அடிவளிமண்டலம்","வெளிவளிமண்டலம்","இடைவளிமண்டலம் (Mesosphere)"],"correctAnswer":3,"explanation":"இடைவளிமண்டலம் (Mesosphere) சுமார் 50 கி.மீ முதல் 80 கி.மீ உயரம் வரை பரவியுள்ளது. இங்கு உயரம் அதிகரிக்கும்போது வெப்பநிலை சுமார் -90°C முதல் -100°C வரை குறையும்; விண்வெளியிலிருந்து நுழையும் விண்கற்கள் இவ்வடுக்கிலேயே எரிந்து சாம்பலாகின்றன.","difficulty":"medium","topic":"வளிமண்டல அடுக்குகள்"},{"id":535,"subject":"gk","testNumber":6,"question":"புவியிலிருந்து அனுப்பப்படும் வானொலி அலைகளைத் திருப்பி அனுப்பித் தொலைத்தொடர்புக்கு உதவும் அயனமண்டலம் (Ionosphere) எந்த அடுக்கின் கீழ்ப்பகுதியில் உள்ளது?","options":["அடுக்குவளிமண்டலம்","இடைவளிமண்டலம்","வெப்பவளிமண்டலம் (Thermosphere)","அடிவளிமண்டலம்"],"correctAnswer":2,"explanation":"வெப்பவளிமண்டலத்தின் (Thermosphere) கீழ்ப்பகுதியில் மின்னூட்டம் பெற்ற அயனிகள் நிறைந்த அயனமண்டலம் (Ionosphere) காணப்படுகிறது. இது வானொலி அலைகளைப் புவிக்குப் பிரதிபலிப்பதுடன் துருவப் பகுதிகளில் அரோரா (Aurora) எனும் வண்ண ஒளி நிகழ்வையும் ஏற்படுத்துகிறது.","difficulty":"medium","topic":"வளிமண்டல அடுக்குகள்"},{"id":536,"subject":"gk","testNumber":6,"question":"வளிமண்டல அழுத்தத்தை அளவிடப் பயன்படும் கருவி எது?","options":["அனிமோமீட்டர்","பாரோமீட்டர்","ஹைக்ரோமீட்டர்","தெர்மாமீட்டர்"],"correctAnswer":1,"explanation":"வளிமண்டல அழுத்தத்தை அளவிட 'பாரோமீட்டர்' (காற்றழுத்தமானி) பயன்படுகிறது; இதன் அலகு மில்லிபார் (mb) ஆகும். காற்றின் வேகத்தை அளவிட அனிமோமீட்டரும், காற்றின் ஈரப்பதத்தை அளவிட ஹைக்ரோமீட்டரும் பயன்படுகின்றன.","difficulty":"easy","topic":"காற்றுகள் மற்றும் வளிமண்டல அழுத்தம்"},{"id":537,"subject":"gk","testNumber":6,"question":"துணை அயன உயர் அழுத்த மண்டலத்திலிருந்து பூமத்திய ரேகை தாழ் அழுத்த மண்டலத்தை நோக்கி ஆண்டு முழுவதும் ஒரே திசையில் வீசும் கோள் காற்று எது?","options":["மேலைக் காற்று (Westerlies)","துருவக் காற்று (Polar Winds)","வியாபாரக் காற்று (Trade Winds)","நிலக்காற்று (Land Breeze)"],"correctAnswer":2,"explanation":"வட மற்றும் தென் துணை அயன உயர் அழுத்த மண்டலங்களிலிருந்து (30° அட்சம்) பூமத்திய ரேகை தாழ் அழுத்த மண்டலத்தை (0°) நோக்கி வீசும் காற்றுகள் 'வியாபாரக் காற்றுகள்' எனப்படுகின்றன. பண்டைய காலப் பாய்மரக் கப்பல் வணிகர்கள் இக்காற்றின் உதவியுடன் பயணித்ததால் இப்பெயர் பெற்றது.","difficulty":"medium","topic":"காற்றுகள் மற்றும் வளிமண்டல அழுத்தம்"},{"id":538,"subject":"gk","testNumber":6,"question":"தென் அரைக்கோளத்தில் 40° தெற்கு அட்சப் பகுதியில் தடையின்றி மிக வேகமாக வீசும் மேலைக் காற்றுகள் எவ்வாறு அழைக்கப்படுகின்றன?","options":["கர்ஜிக்கும் நாற்பதுகள் (Roaring Forties)","அமைதி மண்டலம் (Doldrums)","குதிரை அட்சங்கள் (Horse Latitudes)","பருவக் காற்றுகள் (Monsoons)"],"correctAnswer":0,"explanation":"தென் அரைக்கோளத்தில் நிலப்பரப்பு குறைவாகவும் கடற்பரப்பு அதிகமாகவும் இருப்பதால் மேலைக் காற்றுகள் தடையின்றி மிக வேகமாக வீசுகின்றன. இவை 40° அட்சத்தில் 'கர்ஜிக்கும் நாற்பதுகள்', 50° அட்சத்தில் 'சீறும் ஐம்பதுகள்', 60° அட்சத்தில் 'கதறும் அறுபதுகள்' என அழைக்கப்படுகின்றன.","difficulty":"hard","topic":"காற்றுகள் மற்றும் வளிமண்டல அழுத்தம்"},{"id":539,"subject":"gk","testNumber":6,"question":"வட அமெரிக்காவின் ராக்கி மலைத்தொடரின் கிழக்குச் சரிவில் வீசி பனியை விரைவாக உருக்குவதால் 'பனி உண்ணும் காற்று' (Snow Eater) என அழைக்கப்படும் தலக்காற்று எது?","options":["மிஸ்ட்ரல் (Mistral)","சினூக் (Chinook)","சிராக்கோ (Sirocco)","லூ (Loo)"],"correctAnswer":1,"explanation":"சினூக் (Chinook) என்பது வட அமெரிக்காவின் ராக்கி மலையின் கிழக்குச் சரிவுகளில் வீசும் வெப்பமான மற்றும் வறண்ட தலக்காற்று ஆகும். இது குளிர்காலத்தில் வெப்பநிலையைச் சட்டென உயர்த்தி பனியை வேகமாக உருக்குவதால் 'பனி உண்ணும் காற்று' என அழைக்கப்படுகிறது.","difficulty":"hard","topic":"காற்றுகள் மற்றும் வளிமண்டல அழுத்தம்"},{"id":540,"subject":"gk","testNumber":6,"question":"புவியின் சுழற்சியின் காரணமாக வீசும் காற்றுகள் வட அரைக்கோளத்தில் வலப்புறமாகவும் தென் அரைக்கோளத்தில் இடப்புறமாகவும் திசை விலகுவதற்குக் காரணமான விசை எது?","options":["கொரியாலிஸ் விசை","மையநோக்கு விசை","உராய்வு விசை","புவியீர்ப்பு விசை"],"correctAnswer":0,"explanation":"புவி மேற்கிலிருந்து கிழக்காகச் சுழல்வதால் ஏற்படும் 'கொரியாலிஸ் விசை' (Coriolis Force) காற்றுகள் மற்றும் கடல் நீரோட்டங்களின் திசையை விலக்குகிறது. இதன்படி காற்றுகள் வட அரைக்கோளத்தில் வலப்புறமும் தென் அரைக்கோளத்தில் இடப்புறமும் விலகுகின்றன என்பதை ஃபெரல் விதி விளக்குகிறது.","difficulty":"hard","topic":"காற்றுகள் மற்றும் வளிமண்டல அழுத்தம்"},{"id":541,"subject":"gk","testNumber":6,"question":"பூமத்திய ரேகை, கடக ரேகை மற்றும் மகர ரேகை ஆகிய மூன்று முக்கிய அட்சக்கோடுகளும் கடந்து செல்லும் உலகின் ஒரே கண்டம் எது?","options":["தென் அமெரிக்கா","ஆசியா","ஆப்பிரிக்கா","ஆஸ்திரேலியா"],"correctAnswer":2,"explanation":"பரப்பளவில் உலகின் இரண்டாவது பெரிய கண்டமான ஆப்பிரிக்காவின் வழியாக மட்டுமே பூமத்திய ரேகை (0°), கடக ரேகை (23½° வ) மற்றும் மகர ரேகை (23½° தெ) ஆகிய மூன்று முக்கிய அட்சக்கோடுகளும் கடந்து செல்கின்றன.","difficulty":"easy","topic":"உலகக் கண்டங்கள்"},{"id":542,"subject":"gk","testNumber":6,"question":"பரப்பளவில் உலகின் மிகச்சிறிய கண்டம் மற்றும் 'தீவுக் கண்டம்' என்று அழைக்கப்படும் கண்டம் எது?","options":["ஐரோப்பா","அண்டார்டிகா","ஆஸ்திரேலியா","தென் அமெரிக்கா"],"correctAnswer":2,"explanation":"ஆஸ்திரேலியா நான்கு பக்கமும் பெருங்கடல்களால் சூழப்பட்டிருப்பதால் 'தீவுக் கண்டம்' எனப்படுகிறது. இது உலகின் ஏழு கண்டங்களில் பரப்பளவில் மிகச்சிறிய கண்டமாகும்; உலகப் புகழ்பெற்ற 'பெரும் தடுப்புப் பவளப்பாறை' (Great Barrier Reef) இதன் வடகிழக்குக் கடற்கரையில் அமைந்துள்ளது.","difficulty":"easy","topic":"உலகக் கண்டங்கள்"},{"id":543,"subject":"gk","testNumber":6,"question":"'அறிவியல் கண்டம்' என அழைக்கப்படும் அண்டார்டிகாவில் இந்தியா முதன்முதலில் அமைத்த நிரந்தர ஆராய்ச்சி நிலையம் எது?","options":["பாரதி","ஹிமாத்ரி","தட்சிண கங்கோத்ரி","மைத்ரி"],"correctAnswer":2,"explanation":"பனி படர்ந்த 'வெள்ளைக் கண்டம்' எனப்படும் அண்டார்டிகாவில் இந்தியா 1983–84-ஆம் ஆண்டில் தனது முதல் ஆராய்ச்சி நிலையமான 'தட்சிண கங்கோத்ரி'யை அமைத்தது. அதன்பின்னர் 'மைத்ரி' மற்றும் 'பாரதி' ஆகிய ஆராய்ச்சி நிலையங்களை நிறுவியது (ஹிமாத்ரி என்பது ஆர்க்டிக் பகுதி ஆராய்ச்சி நிலையம்).","difficulty":"medium","topic":"உலகக் கண்டங்கள்"},{"id":544,"subject":"gk","testNumber":6,"question":"உலகின் மிகப்பெரிய மற்றும் ஆழமான பசிபிக் பெருங்கடலில் அமைந்துள்ள புவியின் மிக ஆழமான அகழி எது?","options":["ஜாவா அகழி","பியூர்டோ ரிகோ அகழி","மரியானா அகழி","தென் சாண்ட்விச் அகழி"],"correctAnswer":2,"explanation":"பசிபிக் பெருங்கடலில் அமைந்துள்ள மரியானா அகழியில் உள்ள 'சேலஞ்சர் ஆழம்' (Challenger Deep) சுமார் 10,994 மீட்டர் ஆழம் கொண்டது. இதுவே புவியின் மேற்பரப்பில் அறியப்பட்ட மிக ஆழமான பகுதியாகும்.","difficulty":"easy","topic":"உலகப் பெருங்கடல்கள்"},{"id":545,"subject":"gk","testNumber":6,"question":"ஆங்கில எழுத்து 'S' வடிவத்தில் அமைந்துள்ளதும், உலகின் மிகவும் பரபரப்பான கடல் வாணிபம் நடைபெறுவதுமான பெருங்கடல் எது?","options":["தென் பெருங்கடல்","பசிபிக் பெருங்கடல்","அட்லாண்டிக் பெருங்கடல்","இந்தியப் பெருங்கடல்"],"correctAnswer":2,"explanation":"அட்லாண்டிக் பெருங்கடல் அமெரிக்கா மற்றும் ஐரோப்பா-ஆப்பிரிக்கா கண்டங்களுக்கு இடையே 'S' வடிவத்தில் அமைந்துள்ளது. இதன் வளைந்த கடற்கரைகள் பல இயற்கைத் துறைமுகங்களை உருவாக்குவதால் உலகின் மிகப் பரபரப்பான வணிகப் பெருங்கடலாக விளங்குகிறது.","difficulty":"easy","topic":"உலகப் பெருங்கடல்கள்"},{"id":546,"subject":"gk","testNumber":6,"question":"உலகின் மிக நீளமான ஆறான நைல் நதி ஆப்பிரிக்காக் கண்டத்தில் வடக்கு நோக்கிப் பாய்ந்து எந்தக் கடலில் கலக்கிறது?","options":["செங்கடல்","மத்திய தரைக்கடல்","இந்தியப் பெருங்கடல்","அட்லாண்டிக் பெருங்கடல்"],"correctAnswer":1,"explanation":"சுமார் 6,650 கி.மீ நீளம் கொண்ட நைல் நதி உலகின் மிக நீளமான ஆறாகும். விக்டோரியா ஏரியிலிருந்து தோன்றும் வெள்ளை நைலும், எத்தியோப்பியாவிலிருந்து தோன்றும் நீல நைலும் கார்டூம் நகரில் இணைந்து எகிப்து வழியாகப் பாய்ந்து மத்திய தரைக்கடலில் கலக்கின்றன.","difficulty":"easy","topic":"உலகின் முக்கிய ஆறுகள்"},{"id":547,"subject":"gk","testNumber":6,"question":"நீரின் கொள்ளளவில் (Volume) உலகின் மிகப்பெரிய ஆறு மற்றும் 'புவியின் நுரையீரல்' எனப்படும் மழைக்காடுகளைக் கொண்ட நதி வடிநிலம் எது?","options":["நைல் ஆறு","அமேசான் ஆறு","மிசிசிப்பி ஆறு","காங்கோ ஆறு"],"correctAnswer":1,"explanation":"தென் அமெரிக்காவின் ஆண்டிஸ் மலைத்தொடரில் தோன்றி அட்லாண்டிக் பெருங்கடலில் கலக்கும் அமேசான் ஆறு நீரின் கொள்ளளவில் உலகின் மிகப்பெரிய ஆறாகும். இதன் வடிநிலத்தில் அமைந்துள்ள வெப்பமண்டல மழைக்காடுகள் உலகின் சுமார் 20% ஆக்சிஜனை உற்பத்தி செய்வதால் 'புவியின் நுரையீரல்' எனப்படுகின்றன.","difficulty":"easy","topic":"உலகின் முக்கிய ஆறுகள்"},{"id":548,"subject":"gk","testNumber":6,"question":"ஆசியக் கண்டத்தின் மிக நீளமான ஆறு எது?","options":["யாங்சி ஆறு","மஞ்சள் ஆறு (ஹ்வாங் ஹோ)","பிரம்மபுத்திரா ஆறு","மெகாங் ஆறு"],"correctAnswer":0,"explanation":"சீனாவில் பாயும் யாங்சி (Yangtze) ஆறு சுமார் 6,300 கி.மீ நீளம் கொண்டது; இது ஆசியாவின் மிக நீளமான ஆறும் உலகின் மூன்றாவது நீளமான ஆறும் ஆகும். உலகின் மிகப்பெரிய நீர்மின் திட்டமான 'முப்பள்ளத்தாக்கு அணை' (Three Gorges Dam) இந்த ஆற்றின் குறுக்கே கட்டப்பட்டுள்ளது.","difficulty":"medium","topic":"உலகின் முக்கிய ஆறுகள்"},{"id":549,"subject":"gk","testNumber":6,"question":"வட அமெரிக்காவின் மிக நீளமான நதி அமைப்பான மிசிசிப்பி-மிசௌரி ஆறு எந்தக் கடல் பகுதியில் கலக்கிறது?","options":["மெக்சிகோ வளைகுடா","செயின்ட் லாரன்ஸ் வளைகுடா","பசிபிக் பெருங்கடல்","ஹட்சன் விரிகுடா"],"correctAnswer":0,"explanation":"மிசிசிப்பி மற்றும் அதன் துணை ஆறான மிசௌரி இணைந்து வட அமெரிக்காவின் மிகப்பெரிய நதி அமைப்பை உருவாக்குகின்றன. இது அமெரிக்க ஐக்கிய நாடுகளின் மையப்பகுதி வழியாகத் தெற்கு நோக்கிப் பாய்ந்து மெக்சிகோ வளைகுடாவில் 'பறவைப் பாத டெல்டா'வை (Bird's Foot Delta) உருவாக்கி கலக்கிறது.","difficulty":"medium","topic":"உலகின் முக்கிய ஆறுகள்"},{"id":550,"subject":"gk","testNumber":6,"question":"உலகின் மிகப்பெரிய வெப்பப் பாலைவனமான சஹாரா பாலைவனம் எந்தக் கண்டத்தில் அமைந்துள்ளது?","options":["தென் அமெரிக்கா","ஆப்பிரிக்கா","ஆஸ்திரேலியா","ஆசியா"],"correctAnswer":1,"explanation":"சஹாரா பாலைவனம் ஆப்பிரிக்கக் கண்டத்தின் வடக்குப் பகுதியில் சுமார் 92 லட்சம் சதுர கிலோமீட்டர் பரப்பளவில் பரவியுள்ள உலகின் மிகப்பெரிய வெப்பப் பாலைவனமாகும். இது அட்லாண்டிக் பெருங்கடலிலிருந்து செங்கடல் வரை 11 நாடுகளில் பரவியுள்ளது.","difficulty":"easy","topic":"உலகின் பாலைவனங்கள்"},{"id":551,"subject":"gk","testNumber":6,"question":"ஆசியாவின் மிகப்பெரிய குளிர்ப் பாலைவனமான கோபி பாலைவனம் (Gobi Desert) எந்த இரு நாடுகளில் பரவியுள்ளது?","options":["ஈரான் மற்றும் ஆப்கானிஸ்தான்","கஜகஸ்தான் மற்றும் உஸ்பெகிஸ்தான்","சீனா மற்றும் மங்கோலியா","இந்தியா மற்றும் பாகிஸ்தான்"],"correctAnswer":2,"explanation":"கோபி பாலைவனம் வடக்கு சீனா மற்றும் தெற்கு மங்கோலியா பகுதிகளில் பரவியுள்ள ஆசியாவின் மிகப்பெரிய குளிர்ப் பாலைவனமாகும். இமயமலையின் மழைமறைவுப் பிரதேசத்தில் அமைந்துள்ளதால் இங்கு மழைப்பொழிவு மிகவும் குறைவாக இருக்கும்.","difficulty":"medium","topic":"உலகின் பாலைவனங்கள்"},{"id":552,"subject":"gk","testNumber":6,"question":"உலகிலேயே மிகவும் வறண்ட பாலைவனமான அடகாமா (Atacama) பாலைவனம் எந்தக் கண்டத்தில் அமைந்துள்ளது?","options":["வட அமெரிக்கா","தென் அமெரிக்கா","ஆப்பிரிக்கா","ஆஸ்திரேலியா"],"correctAnswer":1,"explanation":"தென் அமெரிக்காவின் சிலி நாட்டின் வடபகுதியில் பசிபிக் கடற்கரைக்கும் ஆண்டிஸ் மலைக்கும் இடையே அமைந்துள்ள அடகாமா பாலைவனம் உலகின் மிக வறண்ட துருவமற்ற பாலைவனமாகும். இதன் அருகே பாயும் குளிர்ந்த பெரு (ஹம்போல்ட்) நீரோட்டம் இப்பகுதியின் வறட்சிக்கு முக்கியக் காரணமாகும்.","difficulty":"medium","topic":"உலகின் பாலைவனங்கள்"},{"id":553,"subject":"gk","testNumber":6,"question":"உலகின் மிக நீளமான மலைத்தொடரான ஆண்டிஸ் (Andes) மலைத்தொடர் எந்தக் கண்டத்தின் மேற்குப் பகுதியில் அமைந்துள்ளது?","options":["வட அமெரிக்கா","ஆசியா","ஐரோப்பா","தென் அமெரிக்கா"],"correctAnswer":3,"explanation":"சுமார் 7,000 கி.மீ நீளமுள்ள ஆண்டிஸ் மலைத்தொடர் தென் அமெரிக்காவின் மேற்குக் கடற்கரையோரமாக அமைந்துள்ள உலகின் மிக நீளமான மலைத்தொடராகும். இதன் மிக உயரமான சிகரம் அர்ஜென்டினாவில் உள்ள 'அகான்காகுவா' (Aconcagua - 6,961 மீ) ஆகும்.","difficulty":"easy","topic":"உலகின் மலைத்தொடர்கள்"},{"id":554,"subject":"gk","testNumber":6,"question":"ஐரோப்பியக் கண்டத்தின் முக்கிய இளம் மடிப்பு மலைத்தொடரான ஆல்ப்ஸ் (Alps) மலையின் மிக உயரமான சிகரம் எது?","options":["கிளிமஞ்சாரோ","மெக்கின்லி (டெனாலி)","மவுண்ட் பிளாங்க் (Mont Blanc)","அகான்காகுவா"],"correctAnswer":2,"explanation":"பிரான்ஸ் மற்றும் இத்தாலி எல்லையில் அமைந்துள்ள மவுண்ட் பிளாங்க் (4,807 மீ) ஆல்ப்ஸ் மலைத்தொடரின் மிக உயரமான சிகரமாகும். ஆல்ப்ஸ் மலைத்தொடர் சுவிட்சர்லாந்து, பிரான்ஸ், இத்தாலி, ஆஸ்திரியா உள்ளிட்ட 8 ஐரோப்பிய நாடுகளில் பரவியுள்ளது.","difficulty":"hard","topic":"உலகின் மலைத்தொடர்கள்"},{"id":555,"subject":"gk","testNumber":6,"question":"இந்தியாவையும் இலங்கையையும் பிரிக்கும் நீர்ச்சந்தி மற்றும் மன்னார் வளைகுடாவை வங்காள விரிகுடாவுடன் இணைக்கும் நீர்வழி எது?","options":["பாக் நீர்ச்சந்தி","மலாக்கா நீர்ச்சந்தி","பேரிங் நீர்ச்சந்தி","ஹார்முஸ் நீர்ச்சந்தி"],"correctAnswer":0,"explanation":"பாக் நீர்ச்சந்தி (Palk Strait) தமிழ்நாட்டிற்கும் இலங்கையின் வடபகுதிக்கும் இடையே அமைந்து இந்தியாவையும் இலங்கையையும் பிரிக்கிறது. மேலும் இது வங்காள விரிகுடாவையும் மன்னார் வளைகுடாவையும் இணைக்கிறது.","difficulty":"easy","topic":"நீர்ச்சந்திகள் மற்றும் கால்வாய்கள்"},{"id":556,"subject":"gk","testNumber":6,"question":"அட்லாண்டிக் பெருங்கடலையும் மத்திய தரைக்கடலையும் இணைப்பதால் 'மத்திய தரைக்கடலின் திறவுகோல்' என்று அழைக்கப்படும் நீர்ச்சந்தி எது?","options":["டோவர் நீர்ச்சந்தி","மலாக்கா நீர்ச்சந்தி","சுந்தா நீர்ச்சந்தி","ஜிப்ரால்டர் நீர்ச்சந்தி"],"correctAnswer":3,"explanation":"ஜிப்ரால்டர் நீர்ச்சந்தி (Strait of Gibraltar) ஐரோப்பாவின் ஸ்பெயின் நாட்டையும் ஆப்பிரிக்காவின் மொராக்கோ நாட்டையும் பிரித்து, அட்லாண்டிக் பெருங்கடலையும் மத்திய தரைக்கடலையும் இணைக்கிறது. இதன் முக்கியத்துவத்தால் இது 'மத்திய தரைக்கடலின் திறவுகோல்' என அழைக்கப்படுகிறது.","difficulty":"medium","topic":"நீர்ச்சந்திகள் மற்றும் கால்வாய்கள்"},{"id":557,"subject":"gk","testNumber":6,"question":"மத்திய தரைக்கடலையும் செங்கடலையும் இணைத்து ஐரோப்பா மற்றும் ஆசியா இடையேயான கடல் பயணத் தொலைவைப் பெருமளவு குறைத்த கால்வாய் எது?","options":["சூயஸ் கால்வாய்","பனாமா கால்வாய்","கீல் கால்வாய்","சூ கால்வாய்"],"correctAnswer":0,"explanation":"எகிப்து நாட்டில் அமைந்துள்ள சூயஸ் கால்வாய் 1869-ஆம் ஆண்டு போக்குவரத்திற்காகத் திறக்கப்பட்டது. இது மத்திய தரைக்கடலையும் செங்கடலையும் இணைப்பதன் மூலம் ஐரோப்பாவிற்கும் இந்தியாவிற்கும் இடையேயான கடல்வழித் தொலைவை சுமார் 7,000 கி.மீ வரை குறைத்தது.","difficulty":"medium","topic":"நீர்ச்சந்திகள் மற்றும் கால்வாய்கள்"},{"id":558,"subject":"gk","testNumber":6,"question":"அட்லாண்டிக் பெருங்கடலையும் பசிபிக் பெருங்கடலையும் இணைக்கும் பனாமா கால்வாய் எந்த இரு கண்டங்களுக்கு இடையே அமைந்துள்ளது?","options":["ஆசியா மற்றும் வட அமெரிக்கா","ஆசியா மற்றும் ஆப்பிரிக்கா","வட அமெரிக்கா மற்றும் தென் அமெரிக்கா","ஐரோப்பா மற்றும் ஆப்பிரிக்கா"],"correctAnswer":2,"explanation":"1914-ஆம் ஆண்டு திறக்கப்பட்ட பனாமா கால்வாய் வட அமெரிக்காவையும் தென் அமெரிக்காவையும் இணைக்கும் பனாமா நிலச்சந்தியின் குறுக்கே வெட்டப்பட்டது. இது அட்லாண்டிக் மற்றும் பசிபிக் பெருங்கடல்களை இணைக்கும் மிக முக்கியமான உலகளாவிய கடல் வழித்தடமாகும்.","difficulty":"medium","topic":"நீர்ச்சந்திகள் மற்றும் கால்வாய்கள்"},{"id":559,"subject":"gk","testNumber":6,"question":"ரஷ்யாவின் சைபீரியப் பகுதியில் அமைந்துள்ள உலகின் மிக ஆழமான நன்னீர் ஏரி எது?","options":["பைக்கால் ஏரி","சுப்பீரியர் ஏரி","விக்டோரியா ஏரி","டிடிகாக்கா ஏரி"],"correctAnswer":0,"explanation":"ரஷ்யாவில் உள்ள பைக்கால் ஏரி (Lake Baikal) சுமார் 1,642 மீட்டர் ஆழம் கொண்ட உலகின் மிக ஆழமான நன்னீர் ஏரியாகும். பரப்பளவில் உலகின் மிகப்பெரிய நன்னீர் ஏரி சுப்பீரியர் ஏரி (வட அமெரிக்கா) ஆகும்; மிகப்பெரிய உவர்நீர் ஏரி காஸ்பியன் கடல் ஆகும்.","difficulty":"medium","topic":"உலகின் ஏரிகள் மற்றும் தீவுகள்"},{"id":560,"subject":"gk","testNumber":6,"question":"வட அட்லாண்டிக் மற்றும் ஆர்க்டிக் பெருங்கடல்களுக்கு இடையே அமைந்துள்ள உலகின் மிகப்பெரிய தீவு எது?","options":["கிரீன்லாந்து","போர்னியோ","நியூ கினி","மடகாஸ்கர்"],"correctAnswer":0,"explanation":"சுமார் 21.6 லட்சம் சதுர கிலோமீட்டர் பரப்பளவு கொண்ட கிரீன்லாந்து (Greenland) உலகின் மிகப்பெரிய தீவாகும். புவியியல் ரீதியாக வட அமெரிக்கக் கண்டத்தைச் சேர்ந்த இத்தீவு அரசியல் ரீதியாக டென்மார்க் நாட்டின் தன்னாட்சிப் பகுதியாக உள்ளது.","difficulty":"easy","topic":"உலகின் ஏரிகள் மற்றும் தீவுகள்"},{"id":561,"subject":"gk","testNumber":6,"question":"'சூழல் மண்டலம்' (Ecosystem) என்ற அறிவியல் சொல்லை 1935-ஆம் ஆண்டு முதன்முதலில் அறிமுகப்படுத்திய தாவரவியலாளர் யார்?","options":["எர்னஸ்ட் ஹெக்கல்","எட்வர்ட் வில்சன்","சார்லஸ் டார்வின்","ஏ.ஜி. டான்ஸ்லி"],"correctAnswer":3,"explanation":"ஆங்கிலத் தாவரவியலாளர் ஏ.ஜி. டான்ஸ்லி (A.G. Tansley) 1935-ஆம் ஆண்டு 'சூழல் மண்டலம்' (Ecosystem) என்ற சொல்லை முதன்முதலில் உருவாக்கினார். 'சூழலியல்' (Ecology) என்ற சொல்லை 1866-இல் எர்னஸ்ட் ஹெக்கல் அறிமுகப்படுத்தினார்.","difficulty":"medium","topic":"சுற்றுச்சூழல் மண்டலம்"},{"id":562,"subject":"gk","testNumber":6,"question":"ஒரு சூழல் மண்டலத்தில் சூரிய ஒளியைப் பயன்படுத்தி ஒளிச்சேர்க்கை மூலம் சொந்தமாக உணவைத் தயாரிக்கும் பசுந்தாவரங்கள் எவ்வாறு அழைக்கப்படுகின்றன?","options":["உற்பத்தியாளர்கள்","சிதைப்பவை","முதல்நிலை நுகர்வோர்கள்","இரண்டாம் நிலை நுகர்வோர்கள்"],"correctAnswer":0,"explanation":"பசுந்தாவரங்களும் பாசிகளும் சூரிய ஒளி, நீர் மற்றும் கார்பன் டை ஆக்சைடைப் பயன்படுத்தி உணவு தயாரிப்பதால் அவை 'உற்பத்தியாளர்கள்' (Producers) அல்லது 'தற்சார்பு ஊட்ட உயிரிகள்' (Autotrophs) என அழைக்கப்படுகின்றன. உணவுச் சங்கிலியின் முதல் ஊட்ட நிலை இவையே ஆகும்.","difficulty":"easy","topic":"சுற்றுச்சூழல் மண்டலம்"},{"id":563,"subject":"gk","testNumber":6,"question":"உணவுச் சங்கிலியில் ஒரு ஊட்ட நிலையிலிருந்து அடுத்த ஊட்ட நிலைக்கு 10% ஆற்றல் மட்டுமே கடத்தப்படுகிறது என்ற 'பத்து சதவீத ஆற்றல் விதியை' முன்மொழிந்தவர் யார்?","options":["ரேமண்ட் லிண்டெமன்","யூஜின் ஓடம்","நார்மன் மையர்ஸ்","சார்லஸ் எல்டன்"],"correctAnswer":0,"explanation":"1942-ஆம் ஆண்டு ரேமண்ட் லிண்டெமன் (Raymond Lindeman) '10% ஆற்றல் விதியை' முன்மொழிந்தார். இதன்படி ஒவ்வொரு ஊட்ட நிலையிலும் சுமார் 90% ஆற்றல் சுவாசம், வெப்பம் மற்றும் வளர்சிதை மாற்றத்திற்குப் பயன்பட்டுவிட, மீதமுள்ள 10% ஆற்றல் மட்டுமே அடுத்த ஊட்ட நிலைக்குச் செல்கிறது.","difficulty":"hard","topic":"உணவுச் சங்கிலி மற்றும் உணவு வலை"},{"id":564,"subject":"gk","testNumber":6,"question":"ஒரு சூழல் மண்டலத்தில் பல உணவுச் சங்கிலிகள் ஒன்றோடொன்று பின்னிப் பிணைந்து உருவாக்கும் சிக்கலான உணவுத் தொடர்பு அமைப்பு எவ்வாறு அழைக்கப்படுகிறது?","options":["உணவு வலை","உயிரித் திரள்","ஊட்ட நிலை","ஆற்றல் பிரமிடு"],"correctAnswer":0,"explanation":"இயற்கையில் ஓர் உயிரினம் ஒன்றுக்கு மேற்பட்ட உணவு ஆதாரங்களைச் சார்ந்திருப்பதால் பல உணவுச் சங்கிலிகள் ஒன்றோடொன்று இணைந்து 'உணவு வலை'யை (Food Web) உருவாக்குகின்றன. உணவு வலை சூழல் மண்டலத்திற்கு அதிக நிலைப்புத்தன்மையை அளிக்கிறது.","difficulty":"easy","topic":"உணவுச் சங்கிலி மற்றும் உணவு வலை"},{"id":565,"subject":"gk","testNumber":6,"question":"அனைத்து வகைச் சூழல் மண்டலங்களிலும் எப்போதும் நேரான வடிவத்தில் (Always Upright) மட்டுமே காணப்படும் சூழலியல் பிரமிடு எது?","options":["எண்ணிக்கை பிரமிடு","உயிரித்திரள் பிரமிடு","உயிரினப் பரவல் பிரமிடு","ஆற்றல் பிரமிடு"],"correctAnswer":3,"explanation":"ஆற்றல் ஓட்டம் எப்போதும் ஒரு திசையில் (உற்பத்தியாளரிலிருந்து மேல்நிலை நுகர்வோர் வரை) மட்டுமே செல்வதாலும், ஒவ்வொரு ஊட்ட நிலையிலும் ஆற்றல் வெப்பமாக இழக்கப்படுவதாலும் 'ஆற்றல் பிரமிடு' (Pyramid of Energy) எப்போதும் நேரானதாகவே இருக்கும்.","difficulty":"hard","topic":"உணவுச் சங்கிலி மற்றும் உணவு வலை"},{"id":566,"subject":"gk","testNumber":6,"question":"இறந்த தாவரங்கள் மற்றும் விலங்குகளின் கரிமக் கழிவுகளைச் சிதைத்து ஊட்டச்சத்துக்களை மீண்டும் மண்ணில் சேர்க்கும் 'இயற்கையின் துப்புரவாளர்கள்' என அழைக்கப்படுபவை எவை?","options":["ஊன் உண்ணிகள்","தாவர உண்ணிகள்","பச்சைப் பாசிகள்","பாக்டீரியாக்கள் மற்றும் பூஞ்சைகள்"],"correctAnswer":3,"explanation":"பாக்டீரியாக்கள் மற்றும் பூஞ்சைகள் போன்ற 'சிதைப்பவை' (Decomposers) இறந்த உயிரினங்களின் சிக்கலான கரிமப் பொருட்களை எளிய கனிமப் பொருட்களாக மாற்றி மண்ணிற்குத் திருப்பி அனுப்புகின்றன. இதனால் சூழல் மண்டலத்தில் ஊட்டச்சத்து சுழற்சி தொடர்ந்து நடைபெறுகிறது.","difficulty":"medium","topic":"சுற்றுச்சூழல் மண்டலம்"},{"id":567,"subject":"gk","testNumber":6,"question":"வளிமண்டலத்தில் சல்பர் டை ஆக்சைடு (SO2) காற்று மாசுபாடு உள்ளதா என்பதைக் கண்டறியும் இயற்கை 'உயிரி-காட்டிகளாக' (Bio-indicators) செயல்படுபவை எவை?","options":["பவளப்பாறைகள்","சதுப்புநிலத் தாவரங்கள்","லைக்கன்கள்","ஃபெர்ன்கள்"],"correctAnswer":2,"explanation":"பாசிகளும் பூஞ்சைகளும் இணைந்து வாழும் 'லைக்கன்கள்' (Lichens) காற்று மாசுபாட்டிற்கு, குறிப்பாக சல்பர் டை ஆக்சைடு வாயுவிற்கு மிகுந்த உணர்திறன் கொண்டவை. மாசு அதிகம் உள்ள தொழிற்சாலைப் பகுதிகளில் லைக்கன்கள் வளராமல் அழிந்துவிடுவதால் இவை சிறந்த காற்று மாசு உயிரி-காட்டிகளாகக் கருதப்படுகின்றன.","difficulty":"hard","topic":"காற்று மாசுபாடு"},{"id":568,"subject":"gk","testNumber":6,"question":"1984-ஆம் ஆண்டு டிசம்பர் மாதம் நடைபெற்ற போபால் விஷவாயுப் பேரிடரில் யூனியன் கார்பைடு ஆலையிலிருந்து கசிந்த நச்சு வாயு எது?","options":["கார்பன் மோனாக்சைடு","ஹைட்ரஜன் சல்பைடு","குளோரின் வாயு","மெத்தில் ஐசோசயனேட் (MIC)"],"correctAnswer":3,"explanation":"1984 டிசம்பர் 2–3 இரவில் மத்தியப் பிரதேசத்தின் போபால் நகரில் இருந்த யூனியன் கார்பைடு பூச்சிக்கொல்லி ஆலையிலிருந்து 'மெத்தில் ஐசோசயனேட்' (Methyl Isocyanate - MIC) என்ற கொடிய நச்சு வாயு கசிந்து ஆயிரக்கணக்கான உயிர்களைப் பலி கொண்டது.","difficulty":"medium","topic":"காற்று மாசுபாடு"},{"id":569,"subject":"gk","testNumber":6,"question":"நீர்நிலைகளில் கரிமக் கழிவுகளால் ஏற்பட்டுள்ள மாசுபாட்டின் அளவை மதிப்பிடப் பயன்படும் முக்கியக் குறியீடு எது?","options":["ரிக்டர் அளவுகோல்","டெசிபல் அலகு (dB)","டாப்சன் அலகு (DU)","உயிரிவேதி ஆக்சிஜன் தேவை (BOD)"],"correctAnswer":3,"explanation":"நீரில் உள்ள கரிமக் கழிவுகளை நுண்ணுயிரிகள் சிதைப்பதற்குத் தேவைப்படும் ஆக்சிஜனின் அளவு 'உயிரிவேதி ஆக்சிஜன் தேவை' (Biochemical Oxygen Demand - BOD) எனப்படும். நீரின் BOD மதிப்பு அதிகமாக இருந்தால் அந்நீர் கடுமையாக மாசுபட்டுள்ளது என்று பொருள்.","difficulty":"hard","topic":"நீர் மாசுபாடு"},{"id":570,"subject":"gk","testNumber":6,"question":"விவசாய உரங்கள் மற்றும் கழிவுநீர் கலப்பதால் ஏரிகளில் நைட்ரேட், பாஸ்பேட் அதிகரித்து பாசிகள் மிகுதியாகப் பெருகி நீரின் ஆக்சிஜன் அளவு குறையும் நிகழ்வு எது?","options":["உயிரி உருப்பெருக்கம் (Biomagnification)","நைட்ரஜன் நிலைநிறுத்தம்","மிகை ஊட்டமாதல் (Eutrophication)","நீராவிப்போக்கு"],"correctAnswer":2,"explanation":"நீர்நிலைகளில் ஊட்டச்சத்துக்கள் அதிகமாகச் சேர்வதால் பாசிகள் அளவுக்கு அதிகமாகப் பெருகி (Algal Bloom) நீரின் மேற்பரப்பை மூடி, நீரில் கரைந்துள்ள ஆக்சிஜனைக் குறைத்து மீன்கள் உள்ளிட்ட நீர்வாழ் உயிரினங்களை அழிக்கும் நிகழ்வு 'மிகை ஊட்டமாதல்' (Eutrophication) எனப்படும்.","difficulty":"hard","topic":"நீர் மாசுபாடு"},{"id":571,"subject":"gk","testNumber":6,"question":"தொழிற்சாலைக் கழிவுகளிலிருந்து வெளியேறிய எந்தக் கன உலோகத்தால் மாசுபட்ட மீன்களை உண்பதால் ஜப்பானில் 'மினமாட்டா நோய்' (Minamata Disease) ஏற்பட்டது?","options":["பாதரசம் (Mercury)","தாமிரம் (Copper)","ஆர்சனிக் (Arsenic)","ஈயம் (Lead)"],"correctAnswer":0,"explanation":"ஜப்பானின் மினமாட்டா விரிகுடாவில் தொழிற்சாலைக் கழிவுகள் மூலம் கலந்த மெத்தில் பாதரசம் (Methyl Mercury) மீன்களின் உடலில் சேர்ந்து, அவற்றை உண்ட மனிதர்களுக்குக் கடுமையான நரம்பு மண்டலப் பாதிப்பான 'மினமாட்டா நோய்' ஏற்பட்டது.","difficulty":"medium","topic":"நீர் மாசுபாடு"},{"id":572,"subject":"gk","testNumber":6,"question":"நீர் மற்றும் மண்ணில் கலக்கும் காட்மியம் (Cadmium) உலோக மாசுபாட்டால் மனிதர்களின் எலும்புகளில் கடுமையான வலி மற்றும் பலவீனத்தை ஏற்படுத்தும் நோய் எது?","options":["நீலக் குழந்தை நோய்","மினமாட்டா நோய்","புளோரோசிஸ் நோய்","இடாய்-இடாய் நோய்"],"correctAnswer":3,"explanation":"காட்மியம் (Cadmium) மாசுபாட்டால் ஏற்படும் 'இடாய்-இடாய்' (Itai-Itai - ஜப்பானிய மொழியில் 'வலிக்கிறது-வலிக்கிறது') நோய் முதன்முதலில் ஜப்பானில் கண்டறியப்பட்டது. குடிநீரில் நைட்ரேட் அதிகமாகும்போது 'நீலக் குழந்தை நோயும்', புளோரைடு அதிகமாகும்போது 'புளோரோசிஸ்' நோயும் ஏற்படுகின்றன.","difficulty":"hard","topic":"நீர் மாசுபாடு"},{"id":573,"subject":"gk","testNumber":6,"question":"ஒலி மாசுபாட்டின் செறிவை அளவிடப் பயன்படும் பன்னாட்டு அலகு எது?","options":["ஹெர்ட்ஸ் (Hz)","பாஸ்கல் (Pa)","டெசிபல் (dB)","லூமன் (lm)"],"correctAnswer":2,"explanation":"ஒலியின் உரப்பு அல்லது செறிவு 'டெசிபல்' (Decibel - dB) என்ற அலகால் அளக்கப்படுகிறது. உலக சுகாதார நிறுவனத்தின்படி 85 டெசிபலுக்கு மேல் தொடர்ந்து ஒலியைக் கேட்பது மனிதர்களின் செவித்திறனுக்குக் கடுமையான பாதிப்பை ஏற்படுத்தும்.","difficulty":"easy","topic":"ஒலி மற்றும் நில மாசுபாடு"},{"id":574,"subject":"gk","testNumber":6,"question":"திடக்கழிவு மேலாண்மை மற்றும் நில மாசுபாட்டைக் கட்டுப்படுத்தப் பின்பற்றப்படும் '3R' கொள்கை எவற்றைக் குறிக்கிறது?","options":["அகற்றுதல், எரித்தல், புதைத்தல்","வடிகட்டுதல், காய்ச்சுதல், உலர்த்துதல்","சேகரித்தல், பிரித்தல், கரைத்தல்","குறைத்தல், மறுபயன்பாடு, மறுசுழற்சி"],"correctAnswer":3,"explanation":"சுற்றுச்சூழலுக்கு உகந்த கழிவு மேலாண்மையில் 3R என்பது Reduce (பயன்பாட்டைக் குறைத்தல்), Reuse (மறுபயன்பாடு செய்தல்) மற்றும் Recycle (மறுசுழற்சி செய்தல்) ஆகிய மூன்றைக் குறிக்கிறது. இதன் மூலம் நெகிழி மற்றும் மின்-கழிவு மாசுபாட்டைக் குறைக்கலாம்.","difficulty":"easy","topic":"ஒலி மற்றும் நில மாசுபாடு"},{"id":575,"subject":"gk","testNumber":6,"question":"வளிமண்டல நீராவியுடன் வினைபுரிந்து கந்தக அமிலம் மற்றும் நைட்ரிக் அமிலமாக மாறி 'அமில மழை' (Acid Rain) பெய்யக் காரணமான வாயுக்கள் எவை?","options":["ஹீலியம் மற்றும் ஆர்கான்","ஆக்சிஜன் மற்றும் ஹைட்ரஜன்","மீத்தேன் மற்றும் அம்மோனியா","சல்பர் டை ஆக்சைடு மற்றும் நைட்ரஜன் ஆக்சைடுகள்"],"correctAnswer":3,"explanation":"தொழிற்சாலைகள் மற்றும் வாகனங்களிலிருந்து வெளியேறும் சல்பர் டை ஆக்சைடு (SO2) மற்றும் நைட்ரஜன் ஆக்சைடுகள் (NOx) மழைநீருடன் வினைபுரிந்து சல்பியூரிக் அமிலம் (H2SO4) மற்றும் நைட்ரிக் அமிலமாக (HNO3) மாறிப் பொழிகின்றன. மழைநீரின் pH மதிப்பு 5.6-க்குக் கீழ் குறையும்போது அது அமில மழை எனப்படுகிறது.","difficulty":"medium","topic":"அமில மழை"},{"id":576,"subject":"gk","testNumber":6,"question":"ஆக்ராவில் உள்ள தாஜ்மஹாலின் வெண்ணிறப் பளிங்குக் கற்கள் மஞ்சள் நிறமாக மாறிச் சிதைவடையும் 'பளிங்குப் புற்றுநோய்' (Marble Cancer) ஏற்படுவதற்கு முக்கியக் காரணம் என்ன?","options":["அமில மழை","வெப்ப அலைகள்","நிலத்தடி நீர் வற்றுதல்","ஓசோன் படலச் சிதைவு"],"correctAnswer":0,"explanation":"மதுரா எண்ணெய் சுத்திகரிப்பு ஆலை மற்றும் அருகிலுள்ள தொழிற்சாலைகளிலிருந்து வெளிவரும் சல்பர் டை ஆக்சைடு உருவாக்கும் அமில மழை, தாஜ்மஹாலின் கால்சியம் கார்பனேட் பளிங்குக் கற்களுடன் வினைபுரிந்து அவற்றைச் சிதைக்கிறது. இந்த நிகழ்வு 'பளிங்குப் புற்றுநோய்' எனப்படுகிறது.","difficulty":"medium","topic":"அமில மழை"},{"id":577,"subject":"gk","testNumber":6,"question":"புவி வெப்பமயமாதலுக்கு (Global Warming) மனிதச் செயல்பாடுகளால் மிக அதிகப் பங்களிப்பை அளிக்கும் முதன்மைப் பசுமை இல்ல வாயு எது?","options":["ஆக்சிஜன்","நைட்ரஜன்","கார்பன் டை ஆக்சைடு (CO2)","ஆர்கான்"],"correctAnswer":2,"explanation":"நிலக்கரி, பெட்ரோலியம் போன்ற புதைபடிவ எரிபொருள்களை எரித்தல் மற்றும் காடழிப்பு ஆகியவற்றால் வளிமண்டலத்தில் அதிகரிக்கும் கார்பன் டை ஆக்சைடு (CO2) புவியிலிருந்து வெளியேறும் அகச்சிவப்பு வெப்பக் கதிர்களைத் தடுத்து நிறுத்தி புவி வெப்பமயமாதலுக்கு சுமார் 60% பங்களிக்கிறது.","difficulty":"easy","topic":"பசுமை இல்ல வாயுக்கள் மற்றும் புவி வெப்பமயமாதல்"},{"id":578,"subject":"gk","testNumber":6,"question":"நீர் தேங்கிய நெல் வயல்கள், சதுப்பு நிலங்கள் மற்றும் கால்நடைகளின் செரிமானப் பாதையிலிருந்து அதிகமாக வெளியிடப்படும் பசுமை இல்ல வாயு எது?","options":["குளோரின் (Cl2)","ஓசோன் (O3)","மீத்தேன் (CH4)","சல்பர் டை ஆக்சைடு (SO2)"],"correctAnswer":2,"explanation":"மீத்தேன் (CH4) என்பது 'சதுப்பு நில வாயு' (Marsh Gas) என்றும் அழைக்கப்படும் வலிமையான பசுமை இல்ல வாயுவாகும். இது நீர் தேங்கிய நெல் வயல்கள், கால்நடைகளின் அசைபோடும் செயல்முறை மற்றும் கழிவுக் குப்பைகளில் காற்றில்லா சிதைவின்போது அதிகமாக வெளியிடப்படுகிறது.","difficulty":"medium","topic":"பசுமை இல்ல வாயுக்கள் மற்றும் புவி வெப்பமயமாதல்"},{"id":579,"subject":"gk","testNumber":6,"question":"குளிர்சாதனப் பெட்டிகள் மற்றும் குளிரூட்டிகளில் பயன்படுத்தப்பட்டு, வளிமண்டலத்தின் ஓசோன் படலத்தை மிகக் கடுமையாகச் சிதைக்கும் வேதிப்பொருள் எது?","options":["குளோரோ புளோரோ கார்பன்கள் (CFCs)","நைட்ரஜன் டை ஆக்சைடு","கார்பன் மோனாக்சைடு","ஹைட்ரஜன் பெராக்சைடு"],"correctAnswer":0,"explanation":"குளோரோ புளோரோ கார்பன்களிலிருந்து (CFCs) புறஊதாக் கதிர்களின் வினையால் விடுபடும் தனி குளோரின் அணுக்கள், அடுக்குவளிமண்டலத்தில் உள்ள ஓசோன் (O3) மூலக்கூறுகளை ஆக்சிஜனாக உடைத்து ஓசோன் படலத்தை மெலிதாக்குகின்றன.","difficulty":"easy","topic":"ஓசோன் படலச் சிதைவு"},{"id":580,"subject":"gk","testNumber":6,"question":"வளிமண்டலத்தில் உள்ள ஓசோன் படலத்தின் தடிமனை (செறிவை) அளவிடப் பயன்படும் அலகு எது?","options":["ஆங்ஸ்ட்ராம் அலகு","ஃபேதம் அலகு","டெசிபல் அலகு","டாப்சன் அலகு"],"correctAnswer":3,"explanation":"வளிமண்டல ஓசோன் படலத்தின் தடிமன் 'டாப்சன் அலகு' (Dobson Unit - DU) மூலம் அளவிடப்படுகிறது. 220 டாப்சன் அலகிற்குக் கீழ் ஓசோன் செறிவு குறையும் பகுதி 'ஓசோன் துளை' (Ozone Hole) எனக் குறிப்பிடப்படுகிறது; இது அண்டார்டிகா பகுதியில் முதலில் கண்டறியப்பட்டது.","difficulty":"medium","topic":"ஓசோன் படலச் சிதைவு"},{"id":581,"subject":"gk","testNumber":6,"question":"ஓசோன் படலத்தைச் சிதைக்கும் CFC போன்ற பொருட்களின் உற்பத்தி மற்றும் பயன்பாட்டைக் கட்டுப்படுத்த 1987-ஆம் ஆண்டு கையெழுத்திடப்பட்ட வரலாற்றுச் சிறப்புமிக்க ஒப்பந்தம் எது?","options":["ராம்சார் ஒப்பந்தம்","பேசல் ஒப்பந்தம்","கியோட்டோ ஒப்பந்தம்","மாண்ட்ரீல் ஒப்பந்தம்"],"correctAnswer":3,"explanation":"கனடாவின் மாண்ட்ரீல் நகரில் 1987 செப்டம்பர் 16 அன்று கையெழுத்திடப்பட்ட 'மாண்ட்ரீல் ஒப்பந்தம்' (Montreal Protocol) ஓசோன் படலத்தைச் சிதைக்கும் வேதிப்பொருட்களைப் படிப்படியாக ஒழிப்பதை நோக்கமாகக் கொண்டது. இது உலகின் மிக வெற்றிகரமான சுற்றுச்சூழல் ஒப்பந்தமாகக் கருதப்படுகிறது.","difficulty":"medium","topic":"பன்னாட்டு சுற்றுச்சூழல் ஒப்பந்தங்கள்"},{"id":582,"subject":"gk","testNumber":6,"question":"மாண்ட்ரீல் ஒப்பந்தம் கையெழுத்தான நாளை நினைவுகூரும் வகையில் 'உலக ஓசோன் தினம்' ஒவ்வொரு ஆண்டும் எப்போது கடைப்பிடிக்கப்படுகிறது?","options":["ஏப்ரல் 22","ஜூன் 5","செப்டம்பர் 16","மார்ச் 22"],"correctAnswer":2,"explanation":"1987-ஆம் ஆண்டு செப்டம்பர் 16 அன்று மாண்ட்ரீல் ஒப்பந்தம் கையெழுத்தானதை நினைவுகூரும் விதமாக ஐக்கிய நாடுகள் சபை ஒவ்வொரு ஆண்டும் செப்டம்பர் 16-ஆம் நாளை 'உலக ஓசோன் தினமாக' அறிவித்தது.","difficulty":"medium","topic":"ஓசோன் படலச் சிதைவு"},{"id":583,"subject":"gk","testNumber":6,"question":"வளர்ந்த நாடுகள் பசுமை இல்ல வாயுக்களின் உமிழ்வைக் குறைப்பதைச் சட்டப்பூர்வமாகக் கட்டாயமாக்கிய 1997-ஆம் ஆண்டு ஜப்பானில் கையெழுத்தான ஒப்பந்தம் எது?","options":["ரியோ ஒப்பந்தம்","பாரிஸ் ஒப்பந்தம்","நாகோயா ஒப்பந்தம்","கியோட்டோ ஒப்பந்தம்"],"correctAnswer":3,"explanation":"1997 டிசம்பரில் ஜப்பானின் கியோட்டோ நகரில் ஏற்றுக்கொள்ளப்பட்டு 2005-இல் நடைமுறைக்கு வந்த 'கியோட்டோ ஒப்பந்தம்' (Kyoto Protocol), CO2, மீத்தேன் உள்ளிட்ட ஆறு முக்கியப் பசுமை இல்ல வாயுக்களின் உமிழ்வைக் குறைப்பதை இலக்காகக் கொண்டது.","difficulty":"medium","topic":"பன்னாட்டு சுற்றுச்சூழல் ஒப்பந்தங்கள்"},{"id":584,"subject":"gk","testNumber":6,"question":"புவியின் சராசரி வெப்பநிலை உயர்வைத் தொழிற்புரட்சிக்கு முந்தைய அளவை விட 2°C-க்கு மிகாமலும், முடிந்தவரை 1.5°C-க்குள் கட்டுப்படுத்தவும் இலக்கு நிர்ணயித்த 2015-ஆம் ஆண்டு ஒப்பந்தம் எது?","options":["ஜெனீவா ஒப்பந்தம்","பாரிஸ் பருவநிலை ஒப்பந்தம்","ஸ்டாக்ஹோம் ஒப்பந்தம்","மாண்ட்ரீல் ஒப்பந்தம்"],"correctAnswer":1,"explanation":"2015-ஆம் ஆண்டு பிரான்சின் பாரிஸ் நகரில் நடைபெற்ற COP21 பருவநிலை மாநாட்டில் ஏற்றுக்கொள்ளப்பட்ட 'பாரிஸ் பருவநிலை ஒப்பந்தம்', உலக வெப்பநிலை உயர்வை 2°C-க்கும் கீழாகவும், விரும்பத்தக்க அளவாக 1.5°C-க்குள்ளும் கட்டுப்படுத்த அனைத்து நாடுகளையும் ஒருங்கிணைத்தது.","difficulty":"medium","topic":"பன்னாட்டு சுற்றுச்சூழல் ஒப்பந்தங்கள்"},{"id":585,"subject":"gk","testNumber":6,"question":"ஈரநிலங்களின் (Wetlands) பாதுகாப்பு மற்றும் அறிவார்ந்த பயன்பாட்டிற்காக 1971-ஆம் ஆண்டு ஈரானில் கையெழுத்திடப்பட்ட பன்னாட்டு ஒப்பந்தம் எது?","options":["பேசல் ஒப்பந்தம்","பான் ஒப்பந்தம்","பாரிஸ் ஒப்பந்தம்","ராம்சார் ஒப்பந்தம்"],"correctAnswer":3,"explanation":"1971 பிப்ரவரி 2 அன்று ஈரானின் ராம்சார் நகரில் கையெழுத்திடப்பட்ட 'ராம்சார் ஒப்பந்தம்' பன்னாட்டு முக்கியத்துவம் வாய்ந்த ஈரநிலங்கள் மற்றும் நீர்ப்பறவை வாழிடங்களைப் பாதுகாப்பதை நோக்கமாகக் கொண்டுள்ளது. இந்தியாவில் அதிக எண்ணிக்கையிலான ராம்சார் ஈரநிலங்களைக் கொண்ட மாநிலமாகத் தமிழ்நாடு திகழ்கிறது.","difficulty":"medium","topic":"பல்லுயிர் பாதுகாப்பு மற்றும் ஈரநிலங்கள்"},{"id":586,"subject":"gk","testNumber":6,"question":"ராம்சார் ஒப்பந்தம் கையெழுத்தான நாளை முன்னிட்டு 'உலக ஈரநில தினம்' (World Wetlands Day) ஒவ்வொரு ஆண்டும் எந்த நாளில் கொண்டாடப்படுகிறது?","options":["அக்டோபர் 4","மே 22","மார்ச் 21","பிப்ரவரி 2"],"correctAnswer":3,"explanation":"1971 பிப்ரவரி 2 அன்று ராம்சார் ஒப்பந்தம் ஏற்றுக்கொள்ளப்பட்டதை நினைவுகூரும் வகையில் ஒவ்வொரு ஆண்டும் பிப்ரவரி 2-ஆம் நாள் 'உலக ஈரநில தினமாக' கொண்டாடப்படுகிறது. தமிழ்நாட்டில் உள்ள கோடியக்கரை, பள்ளிக்கரணை, பிச்சாவரம் உள்ளிட்ட பல ஈரநிலங்கள் ராம்சார் தளங்களாக அறிவிக்கப்பட்டுள்ளன.","difficulty":"medium","topic":"பல்லுயிர் பாதுகாப்பு மற்றும் ஈரநிலங்கள்"},{"id":587,"subject":"gk","testNumber":6,"question":"உலக அளவில் அழியும் நிலையில் உள்ள அரிய தாவரங்கள் மற்றும் விலங்கினங்களின் பட்டியலைக் கொண்ட 'சிவப்பு தரவுப் புத்தகத்தை' (Red Data Book) வெளியிடும் அமைப்பு எது?","options":["பன்னாட்டு இயற்கைப் பாதுகாப்பு ஒன்றியம் (IUCN)","உலக வானிலை அமைப்பு (WMO)","உணவு மற்றும் வேளாண்மை அமைப்பு (FAO)","உலக சுகாதார நிறுவனம் (WHO)"],"correctAnswer":0,"explanation":"சுவிட்சர்லாந்தின் கிளாண்ட் நகரைத் தலைமையிடமாகக் கொண்ட பன்னாட்டு இயற்கைப் பாதுகாப்பு ஒன்றியம் (IUCN) 'சிவப்பு தரவுப் புத்தகத்தை' (Red Data Book) பராமரித்து வெளியிடுகிறது. இதில் அழிந்துபோன, மிக அருகிய, அழியும் தருவாயிலுள்ள உயிரினங்களின் விவரங்கள் பதிவு செய்யப்படுகின்றன.","difficulty":"easy","topic":"பல்லுயிர் பாதுகாப்பு மற்றும் ஈரநிலங்கள்"},{"id":588,"subject":"gk","testNumber":6,"question":"இந்தியாவில் வனவிலங்குகளைப் பாதுகாக்கவும், வேட்டையாடுதல் மற்றும் சட்டவிரோத வணிகத்தைத் தடுக்கவும் 'வனவிலங்கு பாதுகாப்புச் சட்டம்' எந்த ஆண்டு இயற்றப்பட்டது?","options":["1968","1972","1980","1970"],"correctAnswer":1,"explanation":"இந்திய நாடாளுமன்றத்தால் 1972-ஆம் ஆண்டு இயற்றப்பட்ட 'வனவிலங்கு பாதுகாப்புச் சட்டம்' (Wildlife Protection Act, 1972) தேசியப் பூங்காக்கள் மற்றும் வனவிலங்கு சரணாலயங்களை அமைப்பதற்கும், அரிய வகை உயிரினங்களை வேட்டையாடுவது தடை செய்யப்படுவதற்கும் வலுவான சட்ட அடிப்படையை வழங்கியது.","difficulty":"medium","topic":"சுற்றுச்சூழல் சட்டங்கள்"},{"id":589,"subject":"gk","testNumber":6,"question":"போபால் விஷவாயுப் பேரிடரைத் தொடர்ந்து இந்தியாவில் சுற்றுச்சூழலைப் பாதுகாக்கவும் மேம்படுத்தவும் ஒருங்கிணைந்த 'சுற்றுச்சூழல் பாதுகாப்புச் சட்டம்' எந்த ஆண்டு இயற்றப்பட்டது?","options":["1986","1981","1992","1974"],"correctAnswer":0,"explanation":"இந்திய அரசியலமைப்புப் பிரிவு 253-இன் கீழ் 1986-ஆம் ஆண்டு 'சுற்றுச்சூழல் பாதுகாப்புச் சட்டம்' (Environment Protection Act, 1986) இயற்றப்பட்டது. நீர் சட்டம் (1974) மற்றும் காற்று சட்டம் (1981) ஆகியவற்றுக்கு இடையே ஒருங்கிணைப்பை ஏற்படுத்துவதால் இது 'குடைச் சட்டம்' (Umbrella Act) என்றும் அழைக்கப்படுகிறது.","difficulty":"medium","topic":"சுற்றுச்சூழல் சட்டங்கள்"},{"id":590,"subject":"gk","testNumber":6,"question":"இந்தியாவின் தேசிய விலங்கான புலிகளின் எண்ணிக்கையைப் பாதுகாக்கவும் பெருக்கவும் 'புலி பாதுகாப்புத் திட்டம்' (Project Tiger) எந்த ஆண்டு தொடங்கப்பட்டது?","options":["1975","1973","1992","1982"],"correctAnswer":1,"explanation":"1973 ஏப்ரல் 1 அன்று இந்திய அரசால் தொடங்கப்பட்ட 'புலி பாதுகாப்புத் திட்டம்' (Project Tiger), உத்தரகாண்டில் உள்ள ஜிம் கார்பெட் தேசியப் பூங்காவில் முதன்முதலில் நடைமுறைப்படுத்தப்பட்டது. இதன் கீழ் தமிழ்நாட்டில் களக்காடு-முண்டந்துறை, ஆனைமலை, முதுமலை, சத்தியமங்கலம், ஸ்ரீவில்லிபுத்தூர்-மேகமலை ஆகிய புலிகள் காப்பகங்கள் உள்ளன.","difficulty":"medium","topic":"வனவிலங்கு பாதுகாப்புத் திட்டங்கள்"},{"id":591,"subject":"gk","testNumber":6,"question":"இந்தியாவில் காட்டு யானைகள், அவற்றின் வாழிடங்கள் மற்றும் வலசை வழித்தடங்களைப் பாதுகாக்க 'யானை பாதுகாப்புத் திட்டம்' (Project Elephant) எந்த ஆண்டு தொடங்கப்பட்டது?","options":["2002","1986","1992","1973"],"correctAnswer":2,"explanation":"இந்திய சுற்றுச்சூழல் மற்றும் வனத்துறை அமைச்சகத்தால் 1992-ஆம் ஆண்டு 'யானை பாதுகாப்புத் திட்டம்' (Project Elephant) தொடங்கப்பட்டது. இது மனித-யானை மோதலைக் குறைத்தல், யானை வழித்தடங்களைப் பாதுகாத்தல் மற்றும் தந்தத்திற்காக யானைகள் வேட்டையாடப்படுவதைத் தடுத்தல் ஆகியவற்றை நோக்கமாகக் கொண்டது.","difficulty":"medium","topic":"வனவிலங்கு பாதுகாப்புத் திட்டங்கள்"},{"id":592,"subject":"gk","testNumber":6,"question":"1973-ஆம் ஆண்டு உத்தரகாண்ட் மாநிலத்தின் சமோலி மாவட்டத்தில் காடுகள் அழிக்கப்படுவதைத் தடுக்க மரங்களைக் கட்டிப்பிடித்துப் போராடிய 'சிப்கோ இயக்கத்திற்கு' தலைமை தாங்கியவர் யார்?","options":["மேதா பட்கர்","சுந்தர்லால் பகுகுணா","சலீம் அலி","பாண்டுரங்க ஹெக்டே"],"correctAnswer":1,"explanation":"'சிப்கோ' என்றால் இந்தியில் 'கட்டிப்பிடித்தல்' என்று பொருள்; சுந்தர்லால் பகுகுணா, சண்டி பிரசாத் பட் மற்றும் கௌரா தேவி ஆகியோரின் தலைமையில் இப்போராட்டம் வெற்றிகரமாக நடைபெற்றது. இதேபோல் கர்நாடகாவில் பாண்டுரங்க ஹெக்டே தலைமையில் 'அப்பிகோ இயக்கம்' நடைபெற்றது.","difficulty":"medium","topic":"சுற்றுச்சூழல் இயக்கங்கள்"},{"id":593,"subject":"gk","testNumber":6,"question":"தாவரங்கள் மற்றும் விலங்கினங்களை அவற்றின் இயற்கையான வாழிடங்களுக்குள்ளேயே (தேசியப் பூங்காக்கள், சரணாலயங்கள், உயிர்க்கோளக் காப்பகங்கள்) பாதுகாக்கும் முறை எவ்வாறு அழைக்கப்படுகிறது?","options":["உறைபனிப் பாதுகாப்பு (Cryopreservation)","அகச்சூழல் பாதுகாப்பு (In-situ Conservation)","விதை வங்கிப் பாதுகாப்பு","புறச்சூழல் பாதுகாப்பு (Ex-situ Conservation)"],"correctAnswer":1,"explanation":"உயிரினங்களை அவற்றின் இயற்கையான வாழிடங்களுக்குள்ளேயே பாதுகாப்பது 'அகச்சூழல் பாதுகாப்பு' (In-situ Conservation) எனப்படும். மாறாக, உயிரியல் பூங்காக்கள், தாவரவியல் பூங்காக்கள் மற்றும் விதை வங்கிகளில் இயற்கை வாழிடத்திற்கு வெளியே பாதுகாப்பது 'புறச்சூழல் பாதுகாப்பு' (Ex-situ Conservation) எனப்படும்.","difficulty":"hard","topic":"பல்லுயிர் பாதுகாப்பு மற்றும் ஈரநிலங்கள்"},{"id":594,"subject":"gk","testNumber":6,"question":"உலக அளவில் அதிக அகணிய உயிரினங்களைக் (Endemic Species) கொண்ட இந்தியாவின் 'பல்லுயிர் வெப்ப மையங்களில்' (Biodiversity Hotspots) தமிழ்நாட்டின் மேற்குப் பகுதியை உள்ளடக்கியது எது?","options":["ஆரவல்லி மலைத்தொடர்","சோட்டா நாக்பூர் பீடபூமி","மேற்குத் தொடர்ச்சி மலை","தார் பாலைவனம்"],"correctAnswer":2,"explanation":"இந்தியாவில் இமயமலை, இந்தோ-பர்மா பகுதி, சுந்தாலாந்து (நிக்கோபார் தீவுகள்) மற்றும் மேற்குத் தொடர்ச்சி மலை ஆகிய 4 பல்லுயிர் வெப்ப மையங்கள் உள்ளன. இதில் மேற்குத் தொடர்ச்சி மலை தமிழ்நாடு, கேரளா உள்ளிட்ட மாநிலங்களில் பரவி அரிய அகணிய உயிரினங்களின் களஞ்சியமாக விளங்குகிறது.","difficulty":"hard","topic":"பல்லுயிர் பாதுகாப்பு மற்றும் ஈரநிலங்கள்"},{"id":595,"subject":"gk","testNumber":6,"question":"ஒவ்வொரு ஆண்டும் ஜூன் 5 அன்று 'உலக சுற்றுச்சூழல் தினம்' கொண்டாடப்படுவதற்கு வித்திட்ட ஐக்கிய நாடுகள் சபையின் முதல் மனித சுற்றுச்சூழல் மாநாடு 1972-இல் எங்கு நடைபெற்றது?","options":["நைரோபி (கென்யா)","ரியோ டி ஜெனிரோ (பிரேசில்)","ஸ்டாக்ஹோம் (ஸ்வீடன்)","ஜோகன்னஸ்பர்க் (தென் ஆப்பிரிக்கா)"],"correctAnswer":2,"explanation":"1972 ஜூன் 5 முதல் 16 வரை ஸ்வீடனின் ஸ்டாக்ஹோம் நகரில் நடைபெற்ற ஐ.நா. மனித சுற்றுச்சூழல் மாநாட்டின் நினைவாகவே ஒவ்வொரு ஆண்டும் ஜூன் 5 உலக சுற்றுச்சூழல் தினமாகக் கொண்டாடப்படுகிறது. இம்மாநாட்டின் விளைவாக ஐ.நா. சுற்றுச்சூழல் திட்டம் (UNEP) உருவாக்கப்பட்டது.","difficulty":"hard","topic":"பன்னாட்டு சுற்றுச்சூழல் ஒப்பந்தங்கள்"},{"id":596,"subject":"gk","testNumber":6,"question":"சூரிய ஒளி ஆற்றலை நேரடியாக மின் ஆற்றலாக மாற்றும் 'சூரிய மின்கலன்கள்' (Photovoltaic Cells) தயாரிப்பில் பயன்படும் முதன்மைக் குறைக்கடத்திப் பொருள் எது?","options":["கார்பன்","சிலிக்கான்","தாமிரம்","அலுமினியம்"],"correctAnswer":1,"explanation":"சூரிய மின்கலன்கள் (Solar Cells) 'சிலிக்கான்' என்ற குறைக்கடத்திப் பொருளால் உருவாக்கப்படுகின்றன; இவை ஒளிமின்னழுத்த விளைவின் (Photovoltaic Effect) மூலம் சூரிய ஒளியை நேரடியாக நேர்திசை மின்சாரமாக (DC) மாற்றுகின்றன. இது சுற்றுச்சூழலை மாசுபடுத்தாத புதுப்பிக்கத்தக்க ஆற்றலாகும்.","difficulty":"medium","topic":"புதுப்பிக்கத்தக்க ஆற்றல் வளங்கள்"},{"id":597,"subject":"gk","testNumber":6,"question":"இந்தியாவின் மிகப்பெரிய காற்றாலை மின் உற்பத்திப் பண்ணைகளில் ஒன்றான 'முப்பந்தல் காற்றாலைப் பண்ணை' தமிழ்நாட்டின் எந்த மாவட்டத்தில் அமைந்துள்ளது?","options":["நீலகிரி","சென்னை","ராமநாதபுரம்","கன்னியாகுமரி"],"correctAnswer":3,"explanation":"கன்னியாகுமரி மாவட்டத்தில் மேற்குத் தொடர்ச்சி மலையின் ஆரல்வாய்மொழிக் கணவாய் அருகே அமைந்துள்ள முப்பந்தல் காற்றாலைப் பண்ணை இந்தியாவின் மிகப்பெரிய காற்றாலை மின் உற்பத்தி மையங்களில் ஒன்றாகும். தமிழ்நாடு இந்தியாவில் காற்றாலை மின் உற்பத்தியில் முன்னணி மாநிலமாக உள்ளது.","difficulty":"easy","topic":"புதுப்பிக்கத்தக்க ஆற்றல் வளங்கள்"},{"id":598,"subject":"gk","testNumber":6,"question":"கால்நடைச் சாணம் மற்றும் கரிமக் கழிவுகளைக் காற்றில்லா நொதித்தலுக்கு உட்படுத்தித் தயாரிக்கப்படும் 'உயிரிவாயுவில்' (Biogas / கோபர் வாயு) சுமார் 60%–75% வரை உள்ள முதன்மை எரிவாயு எது?","options":["புரோப்பேன்","நைட்ரஜன்","ஆக்சிஜன்","மீத்தேன்"],"correctAnswer":3,"explanation":"உயிரிவாயு (Biogas) என்பது விலங்குகளின் சாணம், விவசாயக் கழிவுகள் ஆகியவை காற்றில்லாத நிலையில் மெத்தனோஜென் பாக்டீரியாக்களால் சிதைக்கப்படும்போது உருவாகிறது. இதில் சுமார் 60% முதல் 75% வரை மீத்தேன் (CH4) வாயுவும், மீதம் கார்பன் டை ஆக்சைடு மற்றும் சிறிதளவு ஹைட்ரஜனும் உள்ளன.","difficulty":"easy","topic":"புதுப்பிக்கத்தக்க ஆற்றல் வளங்கள்"},{"id":599,"subject":"gk","testNumber":6,"question":"புவியின் ஆழமான உட்பகுதியிலுள்ள வெப்பப் பாறைகள் மற்றும் வெந்நீர் ஊற்றுகளிலிருந்து மின்சாரம் உற்பத்தி செய்யப் பயன்படும் புதுப்பிக்கத்தக்க ஆற்றல் எது?","options":["அலை ஆற்றல்","புவிவெப்ப ஆற்றல்","உயிரி எரிபொருள் ஆற்றல்","அணுக்கரு ஆற்றல்"],"correctAnswer":1,"explanation":"புவியின் உட்பகுதியில் உள்ள பாறைக்குழம்பின் வெப்பத்தால் உருவாகும் நீராவியைப் பயன்படுத்தி விசையாழிகளைச் சுழற்றி மின்சாரம் தயாரிப்பது 'புவிவெப்ப ஆற்றல்' (Geothermal Energy) எனப்படும். இந்தியாவில் லடாக்கின் பூகா பள்ளத்தாக்கு மற்றும் இமாச்சலப் பிரதேசத்தின் மணிகரன் ஆகியவை முக்கியப் புவிவெப்பப் பகுதிகளாகும்.","difficulty":"medium","topic":"புதுப்பிக்கத்தக்க ஆற்றல் வளங்கள்"},{"id":600,"subject":"gk","testNumber":6,"question":"இந்தியாவிலேயே முதன்முதலாக அனைத்துக் கட்டடங்களிலும் 'மழைநீர் சேகரிப்பு' (Rainwater Harvesting) அமைப்பைச் சட்டப்படி கட்டாயமாக்கிய மாநிலம் மற்றும் ஆண்டு எது?","options":["கேரளா - 1998","கர்நாடகா - 2003","ராஜஸ்தான் - 2005","தமிழ்நாடு - 2001"],"correctAnswer":3,"explanation":"நிலத்தடி நீர்மட்டத்தை உயர்த்தவும் குடிநீர் தட்டுப்பாட்டைத் தவிர்க்கவும் இந்தியாவிலேயே முதன்முதலாகத் தமிழ்நாடு அரசு 2001-ஆம் ஆண்டு அனைத்துக் கட்டடங்களிலும் மழைநீர் சேகரிப்பு அமைப்பைக் கட்டாயமாக்கியது. இதனால் சென்னை உட்பட மாநிலம் முழுவதும் நிலத்தடி நீர்மட்டம் கணிசமாக உயர்ந்தது.","difficulty":"medium","topic":"மழைநீர் சேகரிப்பு"}]);
